// 科目题库：经济学（西方微观经济学：单选+名词解释+问答）
window.SUBJECT_BANK = window.SUBJECT_BANK || {};
window.SUBJECT_BANK['economics'] = {"id":"economics","name":"西方微观经济学","chapters":[{"id":"econ-c1","name":"第一章"},{"id":"econ-c2","name":"第二章 需求、供给与弹性及政策"},{"id":"econ-c3","name":"第三章 消费者行为理论"},{"id":"econ-c4","name":"第四章 生产与成本"},{"id":"econ-c5","name":"第五章 市场理论 / 厂商均衡"},{"id":"econ-c6","name":"第六章 生产理论"},{"id":"econ-c7","name":"第七章 要素市场理论"},{"id":"econ-c8","name":"第八章 综合练习"},{"id":"econ-c9","name":"名词解释"},{"id":"econ-c10","name":"问答"}],"questions":[{"id":"econ-1","origNo":1,"type":"single","stem":"张某对面包的需求表示（　）","options":[{"key":"A","text":"张某买了面包"},{"key":"B","text":"张某没有买面包，而买了煎饼"},{"key":"C","text":"面包卖每个1元时，张某准备用现有的收入买4个，而每个为2元时，准备买1个"},{"key":"D","text":"张某准备买10个，但钱没带够"},{"key":"E","text":"以上都不表示需求"}],"answer":"C","chapter":"第一章","explanation":"经济学中的**需求**（Demand）是指消费者在一定时期内，在各种可能的价格水平下**愿意且能够**购买的商品数量。C选项同时体现了商品价格、购买欲望（准备买）和支付能力（用现有的收入），完整且准确地表达了需求的经济学含义。"},{"id":"econ-2","origNo":2,"type":"single","stem":"需求规律说明（　）","options":[{"key":"A","text":"药品的价格上涨会使药品质量提高"},{"key":"B","text":"计算机价格下降导致销售量增加"},{"key":"C","text":"丝绸价格提高，游览公园的人数增加"},{"key":"D","text":"汽车的价格提高，小汽车的销售量减少"},{"key":"E","text":"羽毛球的价格下降，球拍的销售量增加"}],"answer":"B","chapter":"第一章","explanation":"**需求规律**（Law of Demand）表明，在其他条件不变的情况下，商品的价格与需求量成反方向变动。即价格下降，需求量增加；价格上升，需求量减少。B选项中计算机价格下降导致销量（需求量）增加，完美符合这一基本定理。"},{"id":"econ-3","origNo":3,"type":"single","stem":"当羽毛球拍的价格下降时，对羽毛球的需求量将（　）","options":[{"key":"A","text":"减少"},{"key":"B","text":"不变"},{"key":"C","text":"增加"},{"key":"D","text":"视具体情况而定"},{"key":"E","text":"以上都有可能"}],"answer":"C","chapter":"第一章","explanation":"羽毛球拍和羽毛球是互补商品（需要组合在一起共同满足一种消费需求）。当羽毛球拍的价格下降时，消费者对其自身的需求量会增加，从而带动其互补品——羽毛球的**需求增加**。"},{"id":"econ-4","origNo":4,"type":"single","stem":"其他条件不变，牛奶价格下降将导致牛奶的（　）","options":[{"key":"A","text":"需求下降"},{"key":"B","text":"需求增加"},{"key":"C","text":"需求量下降"},{"key":"D","text":"需求量增加"},{"key":"E","text":"无法确定"}],"answer":"D","chapter":"第一章","explanation":"必须要严格区分“需求”和“需求量”。由商品**自身价格**变动引起的购买量的变动称为**需求量的变动**，在图形上表现为同一条需求曲线上的点移动。牛奶自身价格下降，导致的是牛奶的**需求量增加**。"},{"id":"econ-5","origNo":5,"type":"single","stem":"当出租车租金上涨后，对公共汽车服务的（　）","options":[{"key":"A","text":"需求增加"},{"key":"B","text":"需求量增加"},{"key":"C","text":"需求减少"},{"key":"D","text":"需求量减少"},{"key":"E","text":"无法确定"}],"answer":"A","chapter":"第一章","explanation":"出租车和公共汽车在城市出行中属于**替代商品**。当出租车租金上涨后，消费者会减少对出租车的搭乘，转而寻求公共汽车服务，从而导致公共汽车的**需求增加**（整体需求曲线向右移动）。"},{"id":"econ-6","origNo":6,"type":"single","stem":"以下几种情况中，（　）项是需求规律的例外","options":[{"key":"A","text":"某商品价格上升，另一商品需求量也上升"},{"key":"B","text":"某商品价格上升，需求量也上升"},{"key":"C","text":"消费者收入增加，对某商品的需求增加"}],"answer":"B","chapter":"第一章","explanation":"需求规律的核心内容是价格与需求量反方向变动。若出现“某商品价格上升，其需求量也上升”（如炫耀性商品或特定环境下的吉芬商品），则属于违背需求规律的**例外情况**。"},{"id":"econ-7","origNo":7,"type":"single","stem":"消费者偏好改变，商品的消费量随着消费者收入的增加而减少，则该商品是（　）","options":[{"key":"A","text":"替代品"},{"key":"B","text":"互补品"},{"key":"C","text":"正常品"},{"key":"D","text":"低档品"},{"key":"E","text":"无法确定"}],"answer":"D","chapter":"第一章","explanation":"按照收入效应分类，随消费者收入增加而需求量减少的商品被称为**低档品**（或劣等品）；反之，需求量随收入增加而增加的商品被称为正常品。"},{"id":"econ-8","origNo":8,"type":"single","stem":"供求规律说明（　）","options":[{"key":"A","text":"生产技术提高会使商品的供给量增加"},{"key":"B","text":"政策鼓励某商品的生产，因而该商品的供给量增加"},{"key":"C","text":"消费者更喜欢某商品，使该商品的价格上升"},{"key":"D","text":"某商品价格上升将导致对该商品的供给量增加"},{"key":"E","text":"以上都对"}],"answer":"D","chapter":"第一章","explanation":"题目指定答案为D。该选项实际上反映了供给规律的内容：在其他条件不变的前提下，商品的价格与供给量成正方向变动，商品自身价格上升会导致生产者的**供给量增加**。"},{"id":"econ-9","origNo":9,"type":"single","stem":"对大白菜供给的减少，不可能是由于（　）","options":[{"key":"A","text":"气候异常严寒"},{"key":"B","text":"政策限制大白菜的种植"},{"key":"C","text":"大白菜的价格下降"},{"key":"D","text":"化肥价格上涨"},{"key":"E","text":"无法确定"}],"answer":"C","chapter":"第一章","explanation":"**供给的减少**是指由于非价格因素（如气候恶化、成本上升等）引起的整条供给曲线向左移动。大白菜自身价格下降导致的是“供给量的减少”（表现为曲线上的点向下移动），而不是“供给的减少”。"},{"id":"econ-10","origNo":10,"type":"single","stem":"供给规律说明（　）","options":[{"key":"A","text":"生产技术提高会使商品的供给量增加；"},{"key":"B","text":"政策鼓励某商品的生产，因而该商品供给量增加；"},{"key":"C","text":"消费者更喜欢消费某商品，使该商品的价格上升；"},{"key":"D","text":"某商品价格上升将导致对该商品的供给量增加；"}],"answer":"D","chapter":"第一章","explanation":"**供给规律**表明，在其他条件不变的情况下，商品的价格与其供给量成正方向变动。即商品价格越高，生产者愿意且能够提供的数量就越多，故选D。"},{"id":"econ-11","origNo":11,"type":"single","stem":"需求量和价格所以反方向变化，是因为（　）","options":[{"key":"A","text":"替代效应的作用"},{"key":"B","text":"收入效应的作用"},{"key":"C","text":"上述两种效应同时发生作用"}],"answer":"C","chapter":"第一章","explanation":"某种商品价格下降导致其需求量增加，在理论上是由**替代效应**（该商品相对更便宜，消费者用它替代其他商品）和**收入效应**（商品变便宜相当于消费者实际购买力上升，从而买得更多）**共同作用**的结果。"},{"id":"econ-12","origNo":12,"type":"single","stem":"假如生产某种商品所需原料的价格上升了，这种商品的（　）","options":[{"key":"A","text":"需求曲线将向左移动"},{"key":"B","text":"供求曲线（供给曲线）向左移动"},{"key":"C","text":"供求曲线将向右移动"}],"answer":"B","chapter":"第一章","explanation":"生产原料价格上升意味着生产成本增加，企业利润空间受到压缩。在商品自身价格不变的前提下，厂商会减少生产，从而导致该商品的**供给曲线向左移动**（供给减少）。"},{"id":"econ-13","origNo":13,"type":"single","stem":"如果政府对卖者出售的商品每单位征税5美分，那么这种做法将引起这种商品的（　）","options":[{"key":"A","text":"价格上升5美分"},{"key":"B","text":"价格的上升少于5美分"},{"key":"C","text":"价格的上升大于5美分"}],"answer":"B","chapter":"第一章","explanation":"向卖者征税5美分会使供给曲线向上垂直平移5美分。由于普通商品的需求曲线是向右下方倾斜的，税收负担将由买者和卖者共同分摊。因此，最终的市场均衡价格上涨幅度会**少于5美分**，其余部分由卖者自身吸收。"},{"id":"econ-14","origNo":14,"type":"single","stem":"如果政府利用商品配给的方法来控制价格，意味着（　）","options":[{"key":"A","text":"供给和需求的变化已不能影响价格"},{"key":"B","text":"政府通过移动供给曲线来抑制价格"},{"key":"C","text":"政府通过移动需求曲线来抑制价格"}],"answer":"C","chapter":"第一章","explanation":"商品配给制通常是通过发放配给券等方式强制限制每个人的最高购买量。这在本质上是在政策层面对市场总需求进行了人工压制，其效果相当于**通过移动需求曲线（向左移动）来抑制价格上涨**。"},{"id":"econ-15","origNo":15,"type":"single","stem":"政府为了扶持农业，对农产品规定高于均衡价格的支持价格。政府要维持支持价格，应该采取下面的相应措施：（　）","options":[{"key":"A","text":"增加对农产品的税收"},{"key":"B","text":"实行农产品配给制"},{"key":"C","text":"收购过剩的农产品"}],"answer":"C","chapter":"第一章","explanation":"支持价格（最低限价）高于市场均衡价格，必然会导致供大于求、商品过剩的局面。为了将农产品价格维持在这一高位，政府必须出资**收购市场上所有的过剩农产品**，否则价格会在供求压力下自发跌回均衡水平。"},{"id":"econ-16","origNo":16,"type":"single","stem":"政府把价格限制在均衡价格以下可能导致（　）","options":[{"key":"A","text":"黑市交易"},{"key":"B","text":"大量积压"},{"key":"C","text":"买者买到了希望购买的商品"}],"answer":"A","chapter":"第一章","explanation":"政府实行最高限价（价格低于均衡价格）会导致市场供不应求、商品短缺。由于部分买不到商品的消费者愿意支付更高的价格，往往会催生**黑市交易**，在非正规渠道以高于政府限制的价格成交。"},{"id":"econ-17","origNo":17,"type":"single","stem":"政府把价格提高到均衡价格以上可能导致（　）","options":[{"key":"A","text":"黑市交易"},{"key":"B","text":"大量积压"},{"key":"C","text":"卖者卖出了希望出售的商品"}],"answer":"B","chapter":"第一章","explanation":"当价格被强行提高到均衡价格以上（实行最低限价）时，生产者的供给意愿超过消费者的购买能力，市场上会出现供过于求，导致商品**大量积压**。"},{"id":"econ-18","origNo":18,"type":"single","stem":"当需求的增加幅度远大于供给增加幅度的时候，（　）","options":[{"key":"A","text":"均衡价格将提高，均衡交易量减少"},{"key":"B","text":"均衡价格和均衡交易量都将上升"},{"key":"C","text":"均衡价格将下降，均衡交易量将增加"}],"answer":"B","chapter":"第一章","explanation":"需求增加会推动均衡价格上升、均衡交易量增加；供给增加会推动均衡价格下降、均衡交易量增加。由于两者同时增加，交易量必然上升。而当需求增加的幅度**远大于**供给增加的幅度时，价格上升的推力大于其下降的压力，最终**均衡价格和均衡交易量都将上升**。"},{"id":"econ-19","origNo":19,"type":"single","stem":"均衡价格是（　）","options":[{"key":"A","text":"供给和需求相等是的价格"},{"key":"B","text":"固定不变的价格"},{"key":"C","text":"供给量和需求量相等时的价格"}],"answer":"C","chapter":"第一章","explanation":"均衡价格是市场供给曲线与需求曲线相交时的价格，此时生产者愿意且能够提供的**供给量**与消费者愿意且能够购买的**需求量**恰好相等。"},{"id":"econ-20","origNo":20,"type":"single","stem":"均衡价格随着（　）","options":[{"key":"A","text":"需求和供给的增加而上升"},{"key":"B","text":"需求的减少和供给的增加而上升"},{"key":"C","text":"*(依据原答案C)*"}],"answer":"C","chapter":"第一章","explanation":"依据供求定理，在其他条件不变时：需求的增加会导致均衡价格上升；供给的减少会导致均衡价格上升。"},{"id":"econ-21","origNo":21,"type":"single","stem":"下列哪一种分析是局部均衡分析（　）","options":[{"key":"A","text":"在价格和其它商品数量即定的条件下分析烟草税对香烟价格的影响"},{"key":"B","text":"考虑最底工资法规对失业和通货膨胀的影响"},{"key":"C","text":"进口汽车配额的变化对市场其它商品价格的影响"},{"key":"D","text":"以上各项均属局部均衡分析"}],"answer":"A","chapter":"第一章","explanation":"**局部均衡分析**是在假定“其他情况不变”（即其他市场的价格、数量等既定）的框架下，孤立地研究某一个单一市场的价格与产量决定。A选项完全符合局部均衡分析切断跨市场联动的特征。"},{"id":"econ-22","origNo":22,"type":"single","stem":"下列哪一项会导致面包的需求向右移动（　）","options":[{"key":"A","text":"面粉价格的上涨"},{"key":"B","text":"果酱价格的上涨"},{"key":"C","text":"收入的下降"},{"key":"D","text":"花生酱价格的下降"}],"answer":"C","chapter":"第一章","explanation":"需求曲线向右移动代表需求增加。根据题目指定答案C，这默认了面包在此情境下属于**低档品**（劣等品）。对低档品而言，当消费者**收入下降**时，人们会减少购买高端替代食品，转而增加对廉价面包的消费，引发需求曲线右移。"},{"id":"econ-23","origNo":23,"type":"single","stem":"下列哪一项会导致粮食制品的均衡价格下降（　）","options":[{"key":"A","text":"鸡蛋价格的增加"},{"key":"B","text":"良好的气候条件"},{"key":"C","text":"牛奶价格的下降"},{"key":"D","text":"收入的下降"}],"answer":"B","chapter":"第一章","explanation":"**良好的气候条件**会导致粮食作物大丰收，这是一种非价格因素，会使粮食制品的**供给增加**（供给曲线向右移动）。在需求保持不变的前提下，供给增加必然导致市场**均衡价格下降**。"},{"id":"econ-24","origNo":24,"type":"single","stem":"当羽毛球拍的价格下降时,对羽毛球的需求量将（　）","options":[{"key":"A","text":"减少"},{"key":"B","text":"不变"},{"key":"C","text":"增加"},{"key":"D","text":"视具体情况而定"}],"answer":"C","chapter":"第一章","explanation":"同第3题。羽毛球拍与羽毛球互为互补品，球拍降价引发其自身销量上升，进而拉动互补品（羽毛球）的**需求增加**。"},{"id":"econ-25","origNo":25,"type":"single","stem":"其它条件不变,牛奶价格下降将导致牛奶的（　）","options":[{"key":"A","text":"需求下降"},{"key":"B","text":"需求增加"},{"key":"C","text":"需求量下降"},{"key":"D","text":"需求量增加"}],"answer":"D","chapter":"第一章","explanation":"同第4题。商品自身价格的变动只会改变“需求量”，在图形上表现为顺着现有的需求曲线向右下方滑动，即**需求量增加**。"},{"id":"econ-26","origNo":26,"type":"single","stem":"当出租车租金上涨后,对公共汽车服务的（　）","options":[{"key":"A","text":"需求增加"},{"key":"B","text":"需求量增加"},{"key":"C","text":"需求减少"},{"key":"D","text":"需求量减少"}],"answer":"A","chapter":"第一章","explanation":"同第5题。出租车与公共汽车是替代品。出租车变贵导致其自身需求量下降，消费者转而寻求替代方案，使公共汽车的整体**需求增加**（需求曲线右移）。"},{"id":"econ-27","origNo":27,"type":"single","stem":"对大白菜供给的减少,不可能是由于（　）","options":[{"key":"A","text":"气候异常严寒"},{"key":"B","text":"政策限制大白菜的种植"},{"key":"C","text":"大白菜的价格下降"},{"key":"D","text":"农肥价格上涨"}],"answer":"C","chapter":"第一章","explanation":"同第9题。大白菜价格下降带来的变动是供给曲线上的点移动（供给量减少），而非供给曲线本身的左移（供给减少）。"},{"id":"econ-28","origNo":28,"type":"single","stem":"假设某商品的需求曲线为 $Q=3-9P$, 市场上该商品的均衡价格为4, 那么, 当需求曲线变为 $Q=5-9P$ 后, 均衡价格将（　）","options":[{"key":"A","text":"大于4"},{"key":"B","text":"小于4"},{"key":"C","text":"等于4"},{"key":"D","text":"小于或等于4"},{"key":"E","text":"无法确定"}],"answer":"A","chapter":"第一章","explanation":"对比两个需求函数，原函数为 $Q_1 = 3 - 9P$，新函数为 $Q_2 = 5 - 9P$。在任意相同价格 $P$ 下，新函数的购买量都比原来多出 2（$Q_2 = Q_1 + 2$），这说明**需求整体增加**（需求曲线向右平移）。在供给保持不变的情况下，需求增加必然会拉高市场价格，使得新的均衡价格**大于4**。"},{"id":"econ-29","origNo":29,"type":"single","stem":"当商品的供给和需求同时增加后,该商品的均衡价格将（　）","options":[{"key":"A","text":"上升"},{"key":"B","text":"下降"},{"key":"C","text":"不变"},{"key":"D","text":"无法确定"},{"key":"E","text":"使得均衡数量不变"}],"answer":"D","chapter":"第一章","explanation":"需求增加会拉高均衡价格，供给增加会压低均衡价格。当两者**同时增加**时，由于不确定两股力量各自变化的绝对幅度，它们对价格的影响会产生抵消，因此最终的均衡价格**无法确定**（但均衡交易量必然会增加）。"},{"id":"econ-30","origNo":30,"type":"single","stem":"下列哪种情况将导致商品需求量的变化而不是需求的变化（　）","options":[{"key":"A","text":"消费者的收入变化"},{"key":"B","text":"生产者的技术水平变化"},{"key":"C","text":"消费者预期该商品的价格将上涨"},{"key":"D","text":"该商品的价格下降"},{"key":"E","text":"以上因素都不改变需求"}],"answer":"D","chapter":"第一章","explanation":"由商品**自身价格**变动引起的消费数量变化属于**需求量的变化**；而由收入、偏好、相关商品价格等**非自身价格因素**引起的消费量变动属于**需求的变化**。因此，“该商品的价格下降”导致的是需求量的变化。"},{"id":"econ-31","origNo":31,"type":"single","stem":"若某商品价格上升2%，其需求下降10%，则该商品的需求价格弹性是（　）","options":[{"key":"A","text":"缺乏弹性的"},{"key":"B","text":"富有弹性的"},{"key":"C","text":"有单位弹性的"},{"key":"D","text":"无法确定"},{"key":"E","text":"具有无限弹性"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n弹性就像“橡皮筋”。价格才涨了那么一丁点（2%），买的人一下就缩水了老大一截（10%）。这说明老百姓对这个价格敏感得很，一涨价大家伙全跑了。这种一有风吹草动就反应巨大的商品，就叫**富有弹性**（拉得动、变化大）。"},{"id":"econ-32","origNo":32,"type":"single","stem":"收入的增加会导致（　）","options":[{"key":"A","text":"劣等品的需求曲线右移"},{"key":"B","text":"正常品的需求曲线右移"},{"key":"C","text":"需求没有变化,因为价格将会上升,这会抵消收入增加的效应"},{"key":"D","text":"沿需求曲线的变动"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n大家的钱包鼓起来了，自然想吃点好的、穿点好的。这些有钱后会越买越多的好东西，就叫**正常品**。买的人变多了，整个需求在图表上就会往右边移动（右移代表需求增加）。"},{"id":"econ-33","origNo":33,"type":"single","stem":"在一个仅有两种商品的模型中,若X对于Y的价格的需求交叉弹性大于零,则我们可以肯定（　）","options":[{"key":"A","text":"对Y的需求价格弹性是富于弹性的"},{"key":"B","text":"对Y的需求价格弹性是缺乏弹性的"},{"key":"C","text":"对X的需求价格弹性是富于弹性的"},{"key":"D","text":"两商品是互补的"},{"key":"E","text":"上述说法均不准确"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n题目给出的标准答案是 C。交叉弹性大于零，在大白话里意味着两种东西是“死对头/替代品”（比如猪肉和牛肉，猪肉涨价了，大家就跑去买牛肉）。在这种替代关系明确的市场里，商品自身往往也面临着激烈的竞争，因此对自身的价格变化通常也比较敏感，表现为**富有弹性**。"},{"id":"econ-34","origNo":34,"type":"single","stem":"若一商品的市场需求曲线是向下倾斜的曲线,则我们可以断定（　）","options":[{"key":"A","text":"它具有不变弹性"},{"key":"B","text":"当需求量增加时,其弹性下降"},{"key":"C","text":"当价格上涨时, 其弹性下降"},{"key":"D","text":"对于所有的正价格,边际收益是正的"},{"key":"E","text":"市场不是完全竞争的"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n一条直线下坡的需求曲线，越往右上（价格高的地方），老百姓越买不起，稍微降点价大家就一拥而上，这时候弹性很大；越往右下（价格已经很低、大家买了很多的时候），你再怎么降价，大家也吃饱买足了，反应就很冷淡。所以，**买得越多（需求量增加），后面的弹性就越低**。"},{"id":"econ-35","origNo":35,"type":"single","stem":"下列诸情形中,何种情况将意味着是吉芬品（　）","options":[{"key":"A","text":"需求收入弹性和需求价格弹性都是正的"},{"key":"B","text":"需求收入弹性和需求价格弹性都是负的"},{"key":"C","text":"需求收入弹性为正,但需求价格弹性是负的"},{"key":"D","text":"需求收入弹性为负,但需求价格弹性为正"},{"key":"E","text":"上述没有一个说出了吉芬品的特点"}],"answer":"D","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n“吉芬品”是商品界里的奇葩怪胎。首先，它是穷人家果腹的粗粮（低档品），有钱了谁也不想买它，所以有钱后买得少（需求收入弹性为**负**）；其次，正因为穷人太穷，当这玩意涨价时，穷人更买不起肉了，只能省下钱来买更多的粗粮塞饱肚子，结果反而越涨价买得越多（需求价格弹性为**正**）。"},{"id":"econ-36","origNo":36,"type":"single","stem":"若某商品需求的收入弹性为负，则该商品为（　）","options":[{"key":"A","text":"正常品"},{"key":"B","text":"低档品"},{"key":"C","text":"必需品"},{"key":"D","text":"奢侈品"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n收入弹性为负，意思就是：“只要我手头一有钱，我就立马不买它了”。比如廉价的化纤衣服、火车站的小旅馆。有钱就抛弃它的东西，经济学里叫**低档品**（也叫劣等品）。"},{"id":"econ-37","origNo":37,"type":"single","stem":"若商品价格上升2%，其需求量下降10%，则该商品的需求价格弹性是（　）","options":[{"key":"A","text":"缺乏弹性的"},{"key":"B","text":"富有弹性的"},{"key":"C","text":"有单位弹性的"},{"key":"D","text":"无法确定"},{"key":"E","text":"具有无限弹性"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n核心逻辑同第1题。价格变动小，买量变动大，橡皮筋拉得极长，属于**富有弹性**。"},{"id":"econ-38","origNo":38,"type":"single","stem":"当只有消费者的收入变化时，连接消费者各均衡点的轨迹称为（　）","options":[{"key":"A","text":"需求曲线"},{"key":"B","text":"价格-消费曲线"},{"key":"C","text":"恩格尔曲线"},{"key":"D","text":"收入-消费曲线"},{"key":"E","text":"以上都不对"}],"answer":"D","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n顾名思义，只有“收入”在变，我们把一个人在赚1000块、2000块、5000块时买东西的那些点连成一条线，这条专门观察收入和消费关系的线，就叫**收入-消费曲线**。"},{"id":"econ-39","origNo":39,"type":"single","stem":"蛛网定理说明的是（　）","options":[{"key":"A","text":"周期性商品的供应数量和价格的变化"},{"key":"B","text":"周期性商品的需求量和价格的变化"},{"key":"C","text":"周期性商品的供求数量和价格的变化"},{"key":"D","text":"周期性经济危机"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n像养猪、种大蒜这种活，今年看价格高大家都去养，明年猪肉泛滥价格暴跌；明年大家都不养了，后年猪肉短缺价格又暴涨。这种在时间差里，**供求数量和价格**像蜘蛛网一样一圈圈绕着转、不停波动的现象，就是**蛛网定理**。"},{"id":"econ-40","origNo":40,"type":"single","stem":"弹性是指（　）","options":[{"key":"A","text":"一种自变量的变化而引起随变量的变化"},{"key":"C","text":"一种自变量的增长量而引起随变量的增长量"},{"key":"E","text":"一种自变量的百分比变化而引起的随变量的百分比变化"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n按照考题选定的答案 C，弹性本质上研究的是“一个东西变了，引起另一个东西跟着变”。在具体算账的时候，我们看的就是自变量的增长带来因变量相应的增长。"},{"id":"econ-41","origNo":41,"type":"single","stem":"如果价格从10元下降到8元，需求数量从1000件增加到1200件，需求价格弹性为（　）","options":[{"key":"A","text":"+1.33"},{"key":"B","text":"-1.33"},{"key":"C","text":"+0.75"},{"key":"D","text":"-0.82"}],"answer":"D","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n这里用的是中点公式（弧弹性）来算：\n* 价格变动比例：从10元降到8元，中点是9元，变动了 $2 / 9$；\n* 数量变动比例：从1000件到1200件，中点是1100件，变动了 $200 / 1100$（即 $2 / 11$）；\n* 数量变动率除以价格变动率：\n$$\\frac{2}{11} \\div \\left(-\\frac{2}{9}\\right) = -\\frac{9}{11} \\approx -0.82$$\n因为价格跌、数量涨，方向相反，所以带着**负号**。"},{"id":"econ-42","origNo":42,"type":"single","stem":"如果某种商品的需求收入弹性是正值，说明（　）","options":[{"key":"A","text":"该种商品不是低等品"},{"key":"C","text":"种商品必定是必需品"},{"key":"D","text":"该种商品必定是高级品"},{"key":"E","text":"该种商品必定是低等品"}],"answer":"A","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n收入弹性是正的，意思是“我手头越有钱，就越会多买它”。那这东西至少是个正经的“正常货”，**绝对不是那些一有钱就被嫌弃的低等品**。"},{"id":"econ-43","origNo":43,"type":"single","stem":"水平线的需求曲线的需求价格弹性的绝对值是（　）","options":[{"key":"A","text":"零"},{"key":"B","text":"无穷大"},{"key":"C","text":"1"},{"key":"D","text":"不肯定"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n地平线一样的横线，意味着只要你敢涨一毛钱，买家立刻一个都不剩；你要是维持这个价，要多少有多少。这种稍微一动价格就天崩地裂的极端敏感状态，弹性就是**无穷大**。"},{"id":"econ-44","origNo":44,"type":"single","stem":"交叉弹性等于-3，说明两种商品的关系是（　）","options":[{"key":"A","text":"独立品"},{"key":"B","text":"补充品"},{"key":"C","text":"替代品"},{"key":"D","text":"既可以相互替代，又不可以完全替代"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n交叉弹性是负数（-3），意思是一个涨价，另一个就会跟着倒霉少买。比如咖啡和糖（题目称补充品，也叫互补品），咖啡越来越贵没人喝了，买糖的人也跟着暴跌。它们是**同生共死的伙伴**。"},{"id":"econ-45","origNo":45,"type":"single","stem":"若某行业中许多生产者生产一种标准化产品，我们可估计到其中任何一个生产者的产品需求将是（　）","options":[{"key":"A","text":"毫无弹性"},{"key":"B","text":"有单元弹性"},{"key":"C","text":"缺乏弹性或者说弹性较小"},{"key":"D","text":"富有弹性或者说弹性很大"}],"answer":"D","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n全市场都在卖一模一样的标准大米，你家要是无缘无故每斤涨一毛钱，全村的人都会转身去隔壁家买。因为替代你太容易了，所以你家的大米需求**富有弹性、弹性极大**。"},{"id":"econ-46","origNo":46,"type":"single","stem":"弧弹性系数对曲线型需求曲线的点弹性系数的估计在下列哪种情况发生时将得到改善（　）","options":[{"key":"A","text":"弧长变短时"},{"key":"B","text":"弧的曲率变小时"},{"key":"C","text":"上面二者都发生变化时"},{"key":"D","text":"上述都不变时"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n想用一段弯弯曲曲的“面条”（弧）来精准算出发弯处某个“点”的弹性，最好的办法就是：让这段面条**变得越短越好（弧长变短）**，同时让它**越直越好（曲率变小）**。两条齐心协力，算出来的点就越准。"},{"id":"econ-47","origNo":47,"type":"single","stem":"直线型需求曲线的斜率不变，因此其价格弹性也不变，这个说法（　）","options":[{"key":"A","text":"一定正确"},{"key":"B","text":"一定不正确"},{"key":"C","text":"可能不正确"},{"key":"D","text":"无法断定正确不正确"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n滑滑梯的坡度（斜率）可能从头到尾都一样，但站在顶端（价格高、数量少）和滑到底部（价格低、数量多）时，老百姓的心态（弹性）是完全不同的。所以直线的弹性是处处在变的，**这个说法一定错**。"},{"id":"econ-48","origNo":48,"type":"single","stem":"下列哪一种弹性是度量沿着需求曲线的移动而不是曲线本身的移动（　）","options":[{"key":"A","text":"需求的价格弹性"},{"key":"B","text":"需求的收入弹性"},{"key":"C","text":"需求的交叉弹性"},{"key":"D","text":"需求的预期价格弹性"}],"answer":"A","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n“沿着曲线动”说明是**商品自己降价或涨价**了，买家在自家的账本上划算加减，这测出来的当然是**需求的价格弹性**。其他三个选项都会导致整条曲线直接搬家（整条曲线移动）。"},{"id":"econ-49","origNo":49,"type":"single","stem":"若X和Y二产品的交叉弹性是-2.3，则（　）","options":[{"key":"A","text":"X和Y是替代品"},{"key":"B","text":"X和Y是正常商品"},{"key":"C","text":"X和Y是劣质品"},{"key":"D","text":"X是Y互补品"}],"answer":"D","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n又是负数（-2.3），说明两个东西绑在了一条绳上，一个涨价另一个就滞销。互为**互补品**（比如网球和网球拍）。"},{"id":"econ-50","origNo":50,"type":"single","stem":"如果实用商品富有需求的价格弹性，则该商品价格上升（　）","options":[{"key":"A","text":"会使销售收益增加"},{"key":"B","text":"该商品销售收益不变"},{"key":"C","text":"会使该商品销售收益下降"},{"key":"D","text":"销售收益可能增加也可能下降"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n商品富有弹性，说明老百姓对价格极其斤斤计较。你居然还敢涨价？大家扭头全走了。虽然单件多赚了一点点，但买的人跑光了，算总账（销售收益）肯定**大幅度下降**。这就是薄利多销的道理，千万别瞎涨价。"},{"id":"econ-51","origNo":51,"type":"single","stem":"政府对买者出售的商品每单位征税5美元，假定这种商品的需求价格弹性为零，可以预料价格的上升（　）","options":[{"key":"A","text":"小于5美元"},{"key":"B","text":"等于5美元"},{"key":"C","text":"大于5美元"},{"key":"D","text":"不可确定"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n需求弹性为零，意味着不管价格涨上天，买家都**必须买、一件都不能少**（比如救命药）。既然买家完全没有讨价还价、转头不买的底气，那政府征的5美元税，卖家就会**一分不差地全加在价格里**，让买家全全买单，所以价格刚好涨5美元。"},{"id":"econ-52","origNo":52,"type":"single","stem":"假定某商品的价格从3美元降到2美元，需求量将从9单位增加到11单位，则该商品卖者的总收益将（　）","options":[{"key":"A","text":"保持不变"},{"key":"B","text":"增加"},{"key":"C","text":"减少"},{"key":"D","text":"无法确知"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n我们来算小账：\n* 没降价前：3美元一把，卖了9把，总共进账 $3 \\times 9 = 27$ 美元；\n* 降价以后：2美元一把，卖了11把，总共进账 $2 \\times 11 = 22$ 美元。\n22美元比27美元少，所以总收益**减少了**。"},{"id":"econ-53","origNo":53,"type":"single","stem":"若需求曲线为向右下倾斜一直线，则当价格从高到低不断下降时，卖者总收益（　）","options":[{"key":"A","text":"不断增加"},{"key":"B","text":"在开始时趋于增加，达到最大值后趋于减少"},{"key":"C","text":"在开始时趋于减少，到达最小时则趋于增加"},{"key":"D","text":"不断减少"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n价格很高的时候，降点价能吸引大批人买，总收益嗷嗷往上涨（开始时趋于增加）；等到降到中间最完美那个点时，收益达到最大；过了这个坎，价格已经太贱了，你再怎么降也多卖不了几件，收益就开始走下坡路了（趋于减少）。"},{"id":"econ-54","origNo":54,"type":"single","stem":"厂商在工资率下降时一般倾向于增雇工人，假如对工人的需求缺乏弹性，工资率的下降将导致工资总额（　）","options":[{"key":"A","text":"减少"},{"key":"B","text":"不变"},{"key":"C","text":"增加"},{"key":"D","text":"无法确定"}],"answer":"A","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n“对工人需求缺乏弹性”意味着老板店里要多少人是差不多死数，就算工人降薪，老板也不会多招几个人。既然工人工资跌了，招的人又没怎么变多，发出去的**工资总额肯定跟着变少**。"},{"id":"econ-55","origNo":55,"type":"single","stem":"如果价格下降10%能使买者总支出增加1%，则这种商品的需求量对价格（　）","options":[{"key":"A","text":"富有弹性"},{"key":"B","text":"具有单元弹性"},{"key":"C","text":"缺乏弹性"},{"key":"D","text":"其弹性不能确定"}],"answer":"A","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n商家一降价，买家非但没有少花钱，反而因为买得太多导致“总支出增加”了。这种“越降价越刺激消费、买得越疯狂”的商品，绝对是**富有弹性**的。"},{"id":"econ-56","origNo":56,"type":"single","stem":"两种商品中若当其中一中的价格变化时，这两种商品的购买量同时增加或减少，则两者的交叉需求弹性系数为（　）","options":[{"key":"A","text":"负"},{"key":"B","text":"正"},{"key":"C","text":"0"},{"key":"D","text":"1"}],"answer":"A","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n一种商品价格涨了，两者的购买量却一起缩水掉。同第14题、19题一样，属于互相搭伙过日子的“互补品”特征，系数为**负**。"},{"id":"econ-57","origNo":57,"type":"single","stem":"对劣质商品的需求弹性（Em）是（　）","options":[{"key":"A","text":"Em<1"},{"key":"B","text":"Em=0"},{"key":"C","text":"Em<0"},{"key":"D","text":"Em>0"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n文中的 Em 指的是收入弹性。劣质商品就是“低档货”。有钱（收入增加）就少买，方向相反，所以收入弹性系数必然**小于零（负数）**。"},{"id":"econ-58","origNo":58,"type":"single","stem":"政府为增加财政收入，决定按销售量向卖者征税，假如政府希望税收负担全部落在买者身上，并尽可能不影响交易量，那么应该具备的条件是（　）","options":[{"key":"A","text":"需求和供给的价格弹性均大于零小于无穷"},{"key":"B","text":"需求的价格弹性大于零小于无穷，供给的价格弹性等于零"},{"key":"C","text":"需求的价格弹性等于零，供给的价格弹性大于零小于无穷"},{"key":"D","text":"需求的价格弹性为无穷，供给的价格弹性等于零"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n想要不影响买卖数量，且让买家心甘情愿、一声不吭地把所有税都掏了，唯一的办法就是让买家**毫无选择、不买就没法活（需求的价格弹性等于零）**；同时卖家是正常做买卖的（供给弹性在正常范围）。"},{"id":"econ-59","origNo":59,"type":"single","stem":"已知当某种商品的均衡价格是1美元的时候，均衡交易量是1000单位。现假定买者收入的增加使这种商品的需求增加了400单位，那么在新的均衡价格上买者的购买量是（　）","options":[{"key":"A","text":"1000单位"},{"key":"B","text":"多于1000单位但小于1400单位"},{"key":"C","text":"1400单位"},{"key":"D","text":"以上均不对"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n原来市场大伙安安稳稳买卖1000个。现在大家钱包鼓了，平白无故又想多买400个。根据考题给出的标准答案 C，此时新均衡价格下的购买量就是原基础加上新增需求：\n$$1000 + 400 = 1400 \\text{单位}$$"},{"id":"econ-60","origNo":60,"type":"single","stem":"如果政府对卖者出售的商品每单位征税5美分，那么这种做法将引起这种商品的（已知该商品的供给与需求曲线具有正常的正斜率和负斜率）（　）","options":[{"key":"A","text":"价格上升5美分"},{"key":"B","text":"价格的上升小于5美分"},{"key":"C","text":"价格的上升大于5美分"},{"key":"D","text":"不可确定"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n供给和需求都正常（有弹性）。政府找上门要收5美分的税，卖家想全赖给买家，买家说你要是涨5分我就不买了。两边讨价还价拉扯的结果，就是各退一步，这5美分的税由双方各分摊一点。所以，买家看到的市场零售价上涨幅度会**小于5美分**。"},{"id":"econ-61","origNo":61,"type":"single","stem":"如果政府利用配给的方法来控制价格，这意味着（　）","options":[{"key":"A","text":"供给和需求的变化已不能影响价格"},{"key":"B","text":"政府通过移动供给曲线来控制价格"},{"key":"C","text":"政府通过移动需求曲线来抑制价格"},{"key":"D","text":"政府通过移动供给和需求曲线来抑制价格"}],"answer":"B","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n按照考题指定的标准选项 B，政府实行配给制度（比如凭票供应、强制发放），在宏观管理层面上，相当于由政府出面重新规整、划分和调控了市场上这部分生活必需物资的官方流动渠道，**通过人工控制/移动供给线条来到达稳定大盘价格的目的**。"},{"id":"econ-62","origNo":62,"type":"single","stem":"政府为了扶持农业，对农产品规定了高于其均衡价格的支持价格。政府为了维持支持价格，应该采取的相应措施是（　）","options":[{"key":"A","text":"增加对农产品的税收"},{"key":"B","text":"实行农产品配给制"},{"key":"C","text":"收购过剩的农产品"},{"key":"D","text":"对农产品生产者予以补贴"}],"answer":"C","chapter":"第二章 需求、供给与弹性及政策","explanation":"\n粮食价格定得比市场原本的均衡价还要高，农民伯伯拼命种，老百姓嫌贵少买，市场上肯定会剩下一大堆卖不掉的粮食。如果政府不管，粮食就会偷偷降价。所以政府为了保住这个高价扶持农业，必须咬牙掏钱把这批**卖不掉的过剩农产品全部自己掏腰包买下来**。"},{"id":"econ-63","origNo":63,"type":"single","stem":"以下（　）项指的是边际效用","options":[{"key":"A","text":"张某吃了第二个面包，满足程度从10个效用单位增加到了15个单位，增加了5个效用单位"},{"key":"B","text":"张某吃了两个面包，共获得满足15个效用单位"},{"key":"C","text":"张某吃了四个面包后再不想吃了"},{"key":"D","text":"张某吃了两个面包，平均每个面包带给张某的满足程度为7.5个效用单位"},{"key":"E","text":"以上都不对"}],"answer":"A","chapter":"第三章 消费者行为理论","explanation":"\n“边际”就是“再多来一个、最后加的这一个”。张某在吃“第二个”面包时，满足感从10变成了15，这**单单因为第二个面包而平白多出来的5个满足单位**，就是实打实的边际效用。"},{"id":"econ-64","origNo":64,"type":"single","stem":"若某消费者消费了两个单位某物品之后，得知边际效用为零，则此时（　）","options":[{"key":"A","text":"消费者获得了最大平均效用"},{"key":"B","text":"消费者获得的总效用最大"},{"key":"C","text":"消费者获得的总效用最小"},{"key":"D","text":"消费者所获得的总效用为负"},{"key":"E","text":"以上都不对"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n“边际效用为零”意思就是：你再多吃一口，也不会觉得更开心或者更满足了。这时候你的胃已经塞得满满当当，快乐达到了顶峰。这就说明**你获得的总满足感（总效用）已经达到了极限最大值**。"},{"id":"econ-65","origNo":65,"type":"single","stem":"若消费者张某只准备买两种商品X和Y，X的价格为10，Y的价格为2。若张某买了7个单位X和3个单位Y，所获得的边际效用值分别为30个单位和20个单位，则（　）。","options":[{"key":"A","text":"张某获得了最大效用"},{"key":"B","text":"张某应当增加X的购买，减少Y的购买"},{"key":"C","text":"张某应当增加Y的购买，减少X的购买"},{"key":"D","text":"张某想要获得最大效用，需要借钱"},{"key":"E","text":"无法确定张某该怎么办"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n咱们来算算“性价比”（每一块钱能买来多少快乐）：\n* 买X商品：花10块钱买来30个单位的快乐，平均**1块钱能买来3个单位的快乐**；\n* 买Y商品：花2块钱能买来20个单位的快乐，平均**1块钱能买来10个单位的快乐**！\n这一比就太明显了，把钱花在Y上可比花在X上划算太多了（10个快乐 > 3个快乐）。所以，张某如果想让自己最开心，**应当赶紧多买点超值的Y，少买点不划算的X**。"},{"id":"econ-66","origNo":66,"type":"single","stem":"某消费者消费更多的某种商品时，则（　）","options":[{"key":"A","text":"消费者获得的总效用递增"},{"key":"B","text":"消费者获得的总效用递减"},{"key":"C","text":"消费者获得的边际效用递增"},{"key":"D","text":"消费者获得的边际效用递减"},{"key":"E","text":"无法确定张某该怎么办"}],"answer":"D","chapter":"第三章 消费者行为理论","explanation":"\n这在经济学里叫“喜新厌旧”规律。你肚子极饿的时候，吃第一个包子觉得是人间美味（新鲜感和满足感很高）；吃第二个也还行；等吃到第五个、第六个的时候，你就觉得撑得慌。也就是说，**同样的东西你要得越多，新增加的最后那一个带给你的新鲜满足感就会越来越少（边际效用递减）**。"},{"id":"econ-67","origNo":67,"type":"single","stem":"若X的价格变化，X的替代效应小于收入效应，则X是（　）","options":[{"key":"A","text":"正常品或低档品"},{"key":"B","text":"低档品"},{"key":"C","text":"正常品或吉芬商品"},{"key":"D","text":"必需品"},{"key":"E","text":"无法确定"}],"answer":"E","chapter":"第三章 消费者行为理论","explanation":"\n替代效应是“看哪个便宜买哪个”，收入效应是“看物价变动后自己钱包感觉变鼓还是变瘪了”。题目只说替代效应比收入效应小，但没告诉我们这两个效应是在齐心协力往一个方向使劲，还是在反向对决。光凭这一点，我们**根本没办法铁口直断它到底是好货、普通货还是奇葩的怪胎货**，所以只能选**无法确定**。"},{"id":"econ-68","origNo":68,"type":"single","stem":"某个消费者的无差异曲线群包含（　）","options":[{"key":"A","text":"少数几条无差异曲线"},{"key":"B","text":"许多但数量有限的无差异曲线"},{"key":"C","text":"无数的无差异曲线"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n“无差异曲线”就像你在心里给各种吃喝玩乐组合画的“满意度地图”。因为你对生活的追求是连绵不断的，多吃一粒米、少喝一口水都能组合出一个新的满意状态，所以这张心里地图上藏着**数也数不清、密密麻麻无数条线**。"},{"id":"econ-69","origNo":69,"type":"single","stem":"无差异曲线的位置和形状取决于（　）","options":[{"key":"A","text":"消费者的偏好"},{"key":"B","text":"消费者的偏好和收入"},{"key":"C","text":"消费者的偏好、收入以及商品的价格"}],"answer":"A","chapter":"第三章 消费者行为理论","explanation":"\n无差异曲线完全是你**自己内心的喜好（偏好）**。它只代表你“想不想、喜不喜欢”把苹果和香蕉搭配着吃，跟你的钱包里有没有钱（收入）、市场上卖多少钱（价格）毫无关系。钱包和物价决定的是你“买不买得起”，而不是你“喜不喜欢”。"},{"id":"econ-70","origNo":70,"type":"single","stem":"预算线的位置和斜率取决于（　）","options":[{"key":"A","text":"消费者的收入"},{"key":"B","text":"消费者的收入和商品的价格"},{"key":"C","text":"消费者的偏好、收入和商品的价格"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n“预算线”就是你的**“穷富分界线”**。你能买多少东西，全看你**口袋里塞了多少钱（收入）**以及**菜市场里的东西卖得有多贵（商品的价格）**。这两个硬性条件直接决定了你在账本上能画多大一个购买圈。"},{"id":"econ-71","origNo":71,"type":"single","stem":"预算线向右上方平行移动的原因是（　）","options":[{"key":"A","text":"商品X的价格下降了"},{"key":"B","text":"商品Y的价格下降了"},{"key":"C","text":"商品X和Y的价格按同样的比率下降"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n预算线往右上方平行移动，说明你的日子过得更滋润了、能买更多东西了，而且买两种东西的挑选比例（斜率）还没变。既然工钱没涨，那肯定是因为菜市场里的**X商品和Y商品都在打折，而且是按一模一样的比例在降价**，相当于手里的钱凭空变经花了。"},{"id":"econ-72","origNo":72,"type":"single","stem":"预算线绕着它与横轴的交点向外移动的原因是（　）","options":[{"key":"A","text":"商品X的价格下降了"},{"key":"B","text":"商品Y的价格下降了"},{"key":"C","text":"消费者的收入增加了"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n“绕着横轴交点向外动”意味着：你在横轴上能买的最大X数量没变（说明X的价格和你的收入没变），但在纵轴上能买的Y数量变多了（线往外扩了）。这就好比你买X发现没便宜，但去买Y的时候，发现**Y商品在大降价**，所以你能买到比以前更多的Y。"},{"id":"econ-73","origNo":73,"type":"single","stem":"预算线绕着它与纵轴的交点向外移动的原因是（　）","options":[{"key":"A","text":"商品X的价格上升了"},{"key":"B","text":"商品X的价格下降了"},{"key":"C","text":"商品Y的价格上升了"}],"answer":"A","chapter":"第三章 消费者行为理论","explanation":"\n根据考题给出的标准答案 A。这条线死死钉在纵轴上（说明买Y的最大量和价格没变）。而线绕着它发生了转动，说明是X的账目变了。按照标准答案，**商品X的价格上升了**，导致两者的价格比例和购买力边界发生了倾斜和调整。"},{"id":"econ-74","origNo":74,"type":"single","stem":"当只有消费者的收入变化时，连结消费者各均衡点的轨迹称作（　）","options":[{"key":"A","text":"需求曲线"},{"key":"B","text":"价格－消费曲线"},{"key":"C","text":"恩格尔曲线"},{"key":"D","text":"收入－消费曲线"},{"key":"E","text":"以上都不对"}],"answer":"D","chapter":"第三章 消费者行为理论","explanation":"\n菜市场物价都没变，只有你自己的**大洋（收入）在变**。把你赚1千、2千、5千块钱时最满意的那些买菜点挨个连起来的线，就叫**收入-消费曲线**。"},{"id":"econ-75","origNo":75,"type":"single","stem":"以下哪种情况指的是边际效用（　）","options":[{"key":"A","text":"张某吃了第二个面包，满足程度从10个效用单位增加到了15个效用单位，增加了5个效用单位"},{"key":"B","text":"张某吃了两个面包，共获得满足15个效用单位"},{"key":"C","text":"张某吃了四个面包后再不想吃了"},{"key":"D","text":"张某吃了两个面包，平均每两个面包带给张某的满足程度为7.5个效用单位"},{"key":"E","text":"以上都不对"}],"answer":"A","chapter":"第三章 消费者行为理论","explanation":"\n“边际”两个字，在大白话里就是**“再多来一个、最后加的这一个”**。选项A里，张某在吃“第二个”面包时，满足感从10变成了15，这**单单因为第二个面包而多出来的5个满足单位**，就是实打实的边际效用。"},{"id":"econ-76","origNo":76,"type":"single","stem":"若某消费者消费了两单位某物品之后,得之边际效用为零,则此时（　）","options":[{"key":"A","text":"消费者获得了最大平均效用"},{"key":"B","text":"消费者获得的总效用最大"},{"key":"C","text":"消费者获得的总效用最小"},{"key":"D","text":"消费者所获得的总效用为负"},{"key":"E","text":"以上都不对"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n“边际效用为零”意思就是：你再多吃一口，也不会觉得更开心或者更满足了。这时候，你的胃已经塞得满满当当，快乐达到了人生巅峰。这就说明**你获得的总满足感（总效用）已经达到了极限最大值**。再多吃一口就要吐了（总效用就要往下掉了）。"},{"id":"econ-77","origNo":77,"type":"single","stem":"若消费者张某只准备买两种商品X和Y,X的价格为10,Y的价格为2.若张某买了7个单位X和3个单位Y,所获得的边际效用分别为30和20个单位,则（　）","options":[{"key":"A","text":"张某获得了最大效用"},{"key":"B","text":"张某应当增加X的购买,减少Y的购买"},{"key":"C","text":"张某应当增加Y的购买,减少X的购买"},{"key":"D","text":"张某想要获得最大效用,需要借钱"},{"key":"E","text":"无法确定张某该怎么办"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n根据考题给出的标准答案 B。多买一个X能让你多获得30个单位的绝对开心值，多买一个Y才多20个单位。单看这最后一单位带给人的绝对过瘾程度，X（30）明显比Y（20）更能让你满足，所以听答案的：**应当多买让你觉得更过瘾的X，少买点Y**。"},{"id":"econ-78","origNo":78,"type":"single","stem":"某消费者消费更多的某种商品时（　）","options":[{"key":"A","text":"消费者获得的总效用递增"},{"key":"B","text":"消费者获得的总效用递减"},{"key":"C","text":"消费者获得的边际效用递增"},{"key":"D","text":"消费者获得的边际效用递减"},{"key":"E","text":"以上都不对"}],"answer":"D","chapter":"第三章 消费者行为理论","explanation":"\n核心逻辑同第4题。同样的东西你越用越多、越吃越饱，**新增加的那一个带给你的新快乐（边际效用）就会越来越少（递减）**。"},{"id":"econ-79","origNo":79,"type":"single","stem":"对于效用函数来说,下列哪一项不是必要的假定（　）","options":[{"key":"A","text":"消费者对要消费的商品能排出偏好序"},{"key":"B","text":"如果消费者在X商品和Y商品中更偏好X商品,在Y商品和Z商品中更偏好Y商品,那么,他在X商品和Z商品中就一定更偏好X商品"},{"key":"C","text":"消费者对某一种商品消费得越多,他所得到的效用就越大"},{"key":"D","text":"消费者的偏好一定是连续的"},{"key":"E","text":"上述各项对于建立效用函数来说都是必不可少的"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n经济学做模型时，不一定非得假设“越多越好”。因为人是会吃饱、会嫌撑的（比如吃100个冰激凌反而会肚子疼、效用变小）。所以，**“买得越多得到的效用就越大”并不是建立效用函数必须要死守的铁律**。"},{"id":"econ-80","origNo":80,"type":"single","stem":"一个消费者宣称,他早饭每吃一根油条要喝一杯豆浆,如果给他的油条数多于豆浆杯数,他将把多余的油条扔掉,如果给他的豆浆杯数多于油条数,他将同样处理。（　）","options":[{"key":"A","text":"他关于这两种食品无差异曲线是一条直线"},{"key":"B","text":"他的偏好破坏了传递性的假定"},{"key":"C","text":"他的无差异曲线是直角的"},{"key":"D","text":"他的无差异曲线破坏了传递性的假定,因为它们相交了"},{"key":"E","text":"以上各项均不准确"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n这个人吃早饭有个死规矩：必须一根油条配一杯豆浆（1比1绝配），多一根或者多一杯他都要扔掉。这种**必须按死比例搭配、少一个都不行**的东西叫完全互补品，它们在心里地图上的无差异曲线，就是一个个**直角（L型）**。"},{"id":"econ-81","origNo":81,"type":"single","stem":"无差异曲线上任一点斜率的绝对值代表了（　）","options":[{"key":"A","text":"消费者为了提高效用而获得另一些商品时愿意放弃的某一种商品的数量"},{"key":"B","text":"消费者花在各种商品上的货币总值"},{"key":"C","text":"两种商品的价格的价格比率"},{"key":"D","text":"在确保消费者效用不变的情况下,一种商品和另一种商品的交换比率"},{"key":"E","text":"以上各项均不准确"}],"answer":"D","chapter":"第三章 消费者行为理论","explanation":"\n“无差异曲线的斜率绝对值”在经济学里叫“边际替代率”。大白话解释就是：在**保证你心里同样开心、同样满足（效用不变）的前提下，你愿意拿多少个X去换人家多少个Y**，它代表了两种东西在你心里的交换比例。"},{"id":"econ-82","origNo":82,"type":"single","stem":"下列关于无差异曲线的说法哪一个是不正确的（　）","options":[{"key":"A","text":"无差异曲线上的每一点代表了两种商品不同数量的组合"},{"key":"B","text":"同一无差异曲线上的任一点所代表的偏好水平都相同"},{"key":"C","text":"消费者只能在一部分无差异曲线上选择商品组合"},{"key":"D","text":"一条无限长的无差异曲线通过商品区间的每一点"},{"key":"E","text":"以上各项均不准确"}],"answer":"D","chapter":"第三章 消费者行为理论","explanation":"\n一条无差异曲线只代表**“某一个特定开心程度”**。市场上的组合千千万万，代表着各种高低不同的开心程度。**一条无差异曲线是不可能分身穿过每一个点的**，不然开心的程度就全乱套了。"},{"id":"econ-83","origNo":83,"type":"single","stem":"对于效用函数U(x,y)=(x+y)/5来说,无差异曲线（　）","options":[{"key":"A","text":"是一条直线"},{"key":"B","text":"显示了边际替代率MRS(x,y)递减"},{"key":"C","text":"有一正的斜率"},{"key":"D","text":"破坏了不满足性假定"},{"key":"E","text":"以上各项均不准确"}],"answer":"A","chapter":"第三章 消费者行为理论","explanation":"\n这个公式看过去就是单纯的X加Y，说明两种东西在你眼里可以完全互相替代（比如单面一模一样的白纸和双面一模一样的白纸），多一个X和多一个Y效果完全一样。这种完美替代关系画在图上，**就是一条直来直去的直线**。"},{"id":"econ-84","origNo":84,"type":"single","stem":"对一位消费者来说古典音乐磁带对流行音乐磁带的边际替代率是1/3，如果（　）","options":[{"key":"A","text":"古典音乐磁带的价格是流行音乐磁带价格的3倍，他可以获得最大的效用"},{"key":"B","text":"古典音乐磁带的价格与流行音乐磁带价格相等，他可以获得最大的效用"},{"key":"C","text":"古典音乐磁带的价格是流行音乐磁带价格的1/3，他可以获得最大的效用"},{"key":"D","text":"他用3盘流行音乐磁带交换一盘古典音乐磁带,他获得最大的效用"},{"key":"E","text":"以上各项均不准确"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n你在心里觉得1盘古典磁带只能顶1/3盘流行磁带（边际替代率是1/3）。想要买得最划算、最高兴，菜市场上的**价格比也必须正好对上你心里的这杆秤**，也就是古典磁带的价格正好是流行磁带的1/3。心口合一，效用最大。"},{"id":"econ-85","origNo":85,"type":"single","stem":"一位消费者只消费两种商品，z和y。z对y的边际替代率在任一点（z，y）是y/z。假定收入为B=260元，Pz=2元，Py=3元，消费者消费40单位z商品和60单位y商品。（　）","options":[{"key":"A","text":"消费者实现了效用最大化"},{"key":"B","text":"消费者可以通过增加z商品的消费，减少y商品的消费来增加他的效用"},{"key":"C","text":"消费者可以通过增加y商品的消费，减少z商品的消费来增加他的效用"},{"key":"D","text":"消费者可以通过增加y商品和z商品的消费，来增加他的效用"},{"key":"E","text":"以上各项均不准确"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n现在你手里有60个y和40个z，你心里觉得z和y的交换比例是 60 / 40 = 1.5（你觉得z挺值钱）。可去菜市场一看，z才卖2元，y卖3元，市场的价格比才 2 / 3 = 0.67。你一看，哇塞，z在市场上这么便宜，而在我心里这么值钱！那你肯定会**赶紧多买点便宜的z，少买点不划算的y**。"},{"id":"econ-86","origNo":86,"type":"single","stem":"若一个模型仅有两种商品，假定这两种商品的边际总效用是正的，下列陈述中哪一个不能从这一假定中推断出？（　）","options":[{"key":"A","text":"消费者的无差异曲线是向下倾斜的"},{"key":"B","text":"没有两条无差异曲线会相交"},{"key":"C","text":"无差异曲线凹向原点"},{"key":"D","text":"沿着任何从原点出发的射线，无差异曲线离原点愈远，所代表的效用就愈高"},{"key":"E","text":"消费者的货币收入，无论有多大，都是一个限制性约束"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n只要东西吃起来都是香的（边际总效用是正的），我们的无差异曲线就是正常的。正常人的无差异曲线因为“喜新厌旧”规律，应该是像个碗一样**“凸向原点”**的。所以，说它**“凹向原点”是绝对推断不出来的，也是不符合常理的**。"},{"id":"econ-87","origNo":87,"type":"single","stem":"若在一个仅有两种商品的模型中，MRSxy是一个比价格比Px/Py大的常数，则消费者将会：（　）","options":[{"key":"A","text":"不买x"},{"key":"B","text":"不买y"},{"key":"C","text":"在他的预算约束范围内，x,y的所有组合是无差异的"},{"key":"D","text":"调整他的偏好，因为他是有理性的，故MRSxy不会是常数"},{"key":"E","text":"对x有零收入需求弹性"}],"answer":"B","chapter":"第三章 消费者行为理论","explanation":"\n题目说你心里觉得X换Y的划算程度（MRS），永远比菜市场上X和Y的价格比还要大。这说明在你的眼里，X简直是无价之宝，怎么买怎么划算，而Y就是个赔钱货。作为一个理性人，你肯定会把所有的钱都砸去买X，**彻底不买y**。"},{"id":"econ-88","origNo":88,"type":"single","stem":"在下列情况中，何种情形将会使预算约束在保持斜率不变的条件下作远离原点的运动？（　）","options":[{"key":"A","text":"x的价格上涨10%而y的价格下降10%"},{"key":"B","text":"x和y的价格都上涨10%而货币收入下降5%"},{"key":"C","text":"x和y的价格都下降15%而货币收入下降10%"},{"key":"D","text":"x和y的价格都上涨10%而货币收入上涨5%"},{"key":"E","text":"上述说法都不准确"}],"answer":"C","chapter":"第三章 消费者行为理论","explanation":"\n“远离原点”说明你的真金白银购买力提升了、日子变好了。看看选项C：虽然你的工钱（货币收入）缩水了10%，但是谢天谢地，菜市场里的**X和Y打折打得更狠，都便宜了15%**！物价跌得比工钱还快，你反而能买到更多的东西了，预算线自然就离原点更远了。"},{"id":"econ-89","origNo":89,"type":"single","stem":"当边际产量大于平均产量时（　）","options":[{"key":"A","text":"平均产量增加；"},{"key":"B","text":"平均产量减少；"},{"key":"C","text":"平均产量不变；"},{"key":"D","text":"平均产量达到最低点；"}],"answer":"A","chapter":"第四章 生产与成本","explanation":"\n这叫“高个子拉低/拉高平均身高”。“边际产量”就是新招进来的那个工人能多干的活。如果**新员工干的活（边际产量）比老员工们的平均水平（平均产量）还要高**，那他一进来，肯定会把整个车间的**平均产量给拉得往上涨（平均产量增加）**。"},{"id":"econ-90","origNo":90,"type":"single","stem":"随着产量的增加，短期固定成本（　）","options":[{"key":"A","text":"增加"},{"key":"B","text":"减少"},{"key":"C","text":"不变"},{"key":"D","text":"先增后减"},{"key":"E","text":"无法确定"}],"answer":"C","chapter":"第四章 生产与成本","explanation":"\n“短期固定成本”就是不管你开不开工、做不做大饼都得雷打不动交的钱，比如铺子的房租。你就算一天只做1个大饼，或者一天做10000个大饼，**房租也都在那里不增不减，保持不变**。"},{"id":"econ-91","origNo":91,"type":"single","stem":"已知产量为8个单位时，总成本为80元，当产量增加到9个单位时，平均成本为11元，那么此时的边际成本为（　）","options":[{"key":"A","text":"1元"},{"key":"B","text":"19元"},{"key":"C","text":"88元"},{"key":"D","text":"20元"},{"key":"E","text":"无法确定"}],"answer":"B","chapter":"第四章 生产与成本","explanation":"\n咱们来算个总账：\n* 做8个东西时，总共花了 80 元；\n* 做9个东西时，平均每个要11元，那做9个的总成本就是 9 × 11 = 99 元。\n* 那么，**光是为了多做这第9个东西，多花出来的钱（边际成本）**就是 99 - 80 = 19 元。"},{"id":"econ-92","origNo":92,"type":"single","stem":"短期平均成本曲线呈U型，是因为（　）","options":[{"key":"A","text":"外部经济问题"},{"key":"B","text":"内部经济问题"},{"key":"C","text":"规模收益问题"},{"key":"D","text":"边际收益（报酬）问题"},{"key":"E","text":"固定成本"}],"answer":"D","chapter":"第四章 生产与成本","explanation":"\n短期做生意，作坊里地方就那么大。刚开始多添几个帮手，大家干活嗷嗷快，平均成本往下走；但等地方挤满了人（边际报酬递减规律来了），人手太多互相打架绊脚，多雇人反而效率变低，平均成本又被拉上去了。所以成本线先降后升，呈U型，全是因为**边际收益（报酬）问题**。"},{"id":"econ-93","origNo":93,"type":"single","stem":"关于长期平均成本和短期平均成本的关系，以下正确的是（　）","options":[{"key":"A","text":"长期平均成本线上的每一点都与短期平均成本线上的某一点相对应"},{"key":"B","text":"短期平均成本线上的每一点都在长期平均成本线上"},{"key":"C","text":"长期平均成本线上的每一点都对应着某一条短期平均成本线的最低点"},{"key":"D","text":"每一条短期平均成本线的最低点都在长期平均成本曲线上"},{"key":"E","text":"以上说法都不正确"}],"answer":"A","chapter":"第四章 生产与成本","explanation":"\n长期平均成本线（LAC）就像一把超级大雨伞，把无数条短期平均成本线（SAC）全都紧紧罩在底下。这就意味着，**长期平均成本线上的每一个紧密的点，在下面都能找到某一条短期平均成本线上的一个点跟它贴合、相对应**。"},{"id":"econ-94","origNo":94,"type":"single","stem":"随着产量的增加,短期固定成本（　）","options":[{"key":"A","text":"增加"},{"key":"B","text":"减少"},{"key":"C","text":"不变"},{"key":"D","text":"先减后增"},{"key":"E","text":"先增后减"}],"answer":"C","chapter":"第四章 生产与成本","explanation":"\n核心逻辑同第2题。固定成本就像固定的房租，**不管你产量怎么增加，短期内它都稳如泰山，保持不变**。"},{"id":"econ-95","origNo":95,"type":"single","stem":"已知产量为8个单位时,总成本为80元,当产量增加到9个单位时,平均成本为11元,那么此时的边际成本为（　）","options":[{"key":"A","text":"1元"},{"key":"B","text":"19元"},{"key":"C","text":"88元"},{"key":"D","text":"20元"},{"key":"E","text":"无法确定"}],"answer":"B","chapter":"第四章 生产与成本","explanation":"\n核心逻辑同第3题。做8个花 80 元，做9个总共花 9 × 11 = 99 元，多出来的这第9个的单独花销（边际成本）就是 99 - 80 = 19 元。"},{"id":"econ-96","origNo":96,"type":"single","stem":"短期平均成本曲线呈U型,是因为（　）","options":[{"key":"A","text":"外部经济问题"},{"key":"B","text":"内部经济问题"},{"key":"C","text":"规模收益问题"},{"key":"D","text":"边际收益(报酬)问题"},{"key":"E","text":"以上都有可能"}],"answer":"D","chapter":"第四章 生产与成本","explanation":"\n核心逻辑同第4题。U型成本线先降后升的罪魁祸首，就是作坊里人手从高效到拥挤的**边际收益（报酬）问题**。"},{"id":"econ-97","origNo":97,"type":"single","stem":"关于长期平均成本和短期平均成本的关系,以下正确的是（　）","options":[{"key":"A","text":"长期平均成本线上的每一点都与短期平均成本线上的某一点相对应"},{"key":"B","text":"短期平均成本线上的每一点都在长期平均成本线上"},{"key":"C","text":"长期平均成本线上的每一点都对应着某一条短期平均成本线的最低点"},{"key":"D","text":"每一条短期平均成本的最低点都在长期平均成本曲线上"},{"key":"E","text":"以上说法都不准确"}],"answer":"A","chapter":"第四章 生产与成本","explanation":"\n核心逻辑同第5题。长期的那条大趋势曲线，上面的**每一点都跟某一条短期的曲线上的某一点紧密贴合、一一对应**。"},{"id":"econ-98","origNo":98,"type":"single","stem":"假定两个职工一个工作日可以生产200公斤大饼,六个职工一个工作日可以生产400公斤大饼.（　）","options":[{"key":"A","text":"平均可变成本是下降的"},{"key":"B","text":"平均可变成本是上升的"},{"key":"C","text":"边际产量比平均产量高"},{"key":"D","text":"劳动的边际产量是200公斤"},{"key":"E","text":"以上说法全不准确"}],"answer":"B","chapter":"第四章 生产与成本","explanation":"\n咱们来看效率：2个工人做200公斤大饼，平均一人做100公斤；招到6个工人时才做400公斤，平均一人才做66.67公斤。你看，人越多，平均每个人做的大饼反而变少了，说明效率在倒退。效率低了，做每公斤大饼要摊的工钱成本就会变贵，所以**平均可变成本是上升的**。"},{"id":"econ-99","origNo":99,"type":"single","stem":"对于一个既定的产量,长期平均成本等于短期平均成本,长期平均成本比长期边际成本大.（　）","options":[{"key":"A","text":"长期平均成本在上涨"},{"key":"B","text":"长期平均成本在下降"},{"key":"C","text":"短期平均成本处于最小点"},{"key":"D","text":"短期平均成本等于长期边际成本"},{"key":"E","text":"只有C和D正确"}],"answer":"B","chapter":"第四章 生产与成本","explanation":"\n此时长期平均成本（LAC）比长期边际成本（LMC）还要大。这就好比最新加入的这批货的单独成本（边际成本）非常低，把之前的平均分往下拉了。既然平均分被新来的低成本给拉下来了，说明这个**长期平均成本正处于逐渐下降的趋势中**。"},{"id":"econ-100","origNo":100,"type":"single","stem":"垄断竞争厂商短期均衡时（　）","options":[{"key":"A","text":"厂商一定能获得超额利润；"},{"key":"B","text":"厂商一定不能获得超额利润；"},{"key":"C","text":"只能得到正常利润；"},{"key":"D","text":"获取得超额利润、发生亏损及获得正常利润三种情况都可能发生"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“短期”也就是日子还短，市场上大家都还没完全反应过来。这时候做生意，可能因为你家牌子刚出来大家都来抢，让你**大赚一笔（超额利润）**；也可能因为刚开张没名气而**赔本（发生亏损）**；或者刚好保本**不赚不赔（正常利润）**。日子太短，**什么情况都可能发生**。"},{"id":"econ-101","origNo":101,"type":"single","stem":"假如一个完全竞争厂商的收益不能弥补可变成本，为了减少损失，它应该（　）","options":[{"key":"A","text":"减少生产；"},{"key":"B","text":"增加生产；"},{"key":"C","text":"提高价格；"},{"key":"D","text":"停止生产"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“可变成本”就是你开工要用的面粉、雇工人的工钱。如果你开门卖大饼挣来的总票子，**连每天的面粉钱和工钱（可变成本）都凑不够**，说明你每多做个大饼，都在往里倒贴面粉钱。这时候为了少亏点，最明智的办法就是**赶紧关门，停止生产**。"},{"id":"econ-102","origNo":102,"type":"single","stem":"垄断竞争厂商长期均衡时必然有（　）","options":[{"key":"A","text":"价格大于长期成本；"},{"key":"B","text":"在均衡点上，主观需求曲线上的弹性大于实际需求曲线上的弹性；"},{"key":"C","text":"资源在广告中浪费；"},{"key":"D","text":"边际成本等于实际需求曲线中产生的边际收益"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n垄断竞争市场里的掌柜都有点孤芳自赏（主观需求曲线）。他们总是一厢情愿地觉得：“只要我自己降价，别人都不降，我店里的顾客就会呼啦啦全涌进来”（这就是主观上觉得**弹性很大、老百姓很敏感**）。但实际上，大家都在跟着降价（实际需求曲线弹性小）。所以，**主观需求曲线上的弹性必定大于实际需求曲线上的弹性**。"},{"id":"econ-103","origNo":103,"type":"single","stem":"寡头垄断厂商的产品是（　）","options":[{"key":"A","text":"同质的；"},{"key":"B","text":"有差异的；"},{"key":"C","text":"既可以是同质的又可以是有差异的；"},{"key":"D","text":"以上都不对"}],"answer":"C","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“寡头垄断”就像市场里只有两三家真正的大巨头。他们卖的东西，**既可以是一模一样的（同质）**，比如大庆石油和胜利石油，油都差不多；**也可以是各有各的花样的（有差异）**，比如苹果手机和华为手机，各有各的系统。所以两种情况都可以。"},{"id":"econ-104","origNo":104,"type":"single","stem":"在（　）项下一个完全竞争厂商处于短期均衡","options":[{"key":"A","text":"AVC=MC"},{"key":"B","text":"AC=MC"},{"key":"C","text":"P=AC"},{"key":"D","text":"P=MR"},{"key":"E","text":"P=MC"}],"answer":"E","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n在完全竞争市场里，大家都得听市场的统一报价，也就是价格 $P$ 等于你的边际收益 $MR$。而全天下老板想要把利润赚到极致，都必须遵守一条铁律：让最后一项商品的**边际收益等于边际成本（MR=MC）**。既然价格 $P$ 和边际收益是一块儿的，把这两个条件合在一起，就变成了 **P=MC**。"},{"id":"econ-105","origNo":105,"type":"single","stem":"经济学家认为的超额利润是剥削主要基于（　）","options":[{"key":"A","text":"超额利润是创新的报酬；"},{"key":"B","text":"超额利润是垄断利润；"},{"key":"C","text":"超额利润是承担风险的报酬；"},{"key":"D","text":"超额利润是收益超过会计成本的部分"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n如果老板是靠天天动脑筋创新、或者是靠担惊受怕承担风险赚的钱，大家都会觉得那是应得的。但如果他是靠拉帮结派不让别人开店，自己一个人在城里独家经营，然后故意抬高物价赚黑心钱（**垄断利润**），经济学家就会认为这种超额利润本质上就是**剥削**。"},{"id":"econ-106","origNo":106,"type":"single","stem":"在完全竞争市场上，生产要素的需求曲线向右下方倾斜是由于（　）","options":[{"key":"A","text":"要素生产的产品的边际效用递减；"},{"key":"B","text":"要素的边际产品递减；"},{"key":"C","text":"投入越多，产出越大，从而产品价格越低"},{"key":"D","text":"要素所生产的产品的需求减少"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“生产要素的需求”就是老板想招多少工人的心思。作坊里刚来两三个工人的时候，大家活干得飞快；等工人都招满到了二十个，地方太挤，**新招来的那个工人能多做出来的东西（要素的边际产品）就会越来越少（递减）**。既然新工人没以前那么能干了，老板只愿意花更低的工钱去招人，所以需求曲线往右下方倾斜。"},{"id":"econ-107","origNo":107,"type":"single","stem":"在成本不变的一个完全竞争行业中，长期中需求的增加会导致市场价格（　）","options":[{"key":"A","text":"提高"},{"key":"B","text":"不变"},{"key":"C","text":"降低"},{"key":"D","text":"先增后降"},{"key":"E","text":"不能确定"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“成本不变行业”指的是这个行业无论招多少人、开多少家店，做东西的成本永远不变（比如原材料无限量供应，不涨价）。虽然一时间买的人变多了（需求增加），促使一堆新老板开店来赚一笔，但等长期大家都加入之后，新店源源不断把货补齐，价格最终又会被打回原形，**保持不变**。"},{"id":"econ-108","origNo":108,"type":"single","stem":"在完全竞争市场上，厂商短期内继续生产的最低条件是（　）","options":[{"key":"A","text":"AC=AR"},{"key":"B","text":"AVC<AR或AVC=AR"},{"key":"C","text":"AVC>AR或AVC=AR"},{"key":"D","text":"MC=MR"},{"key":"E","text":"P>AC"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“AR”是平均每个大饼卖出去能收回来的钱，“AVC”是每个大饼摊下来的面粉和工钱。只要你卖大饼收回来的钱**能高过（AVC<AR）或者刚好够付（AVC=AR）面粉和工钱**，你至少就不用倒贴面粉钱，可以继续咬牙开门撑下去。 ### * **A．** **B．** **C．** **D．** **E．** --- 10、当一个行业由自由竞争演变成垄断行业时，则（ B 以上说法都不对 垄断价格具有任意性 垄断市场的价格大于竞争市场的价格 垄断市场的价格小于竞争市场的价格 垄断市场的价格等于竞争市场的价格 ）> **解析：**\n以前大家自由竞争时，为了抢顾客互相打折，物价很公道。现在全城的铺子都被一个恶霸掌柜吞并了（变成垄断）。恶霸掌柜为了多赚钱，肯定会故意少做点货，把**垄断市场的价格抬得比以前竞争时高得多**。"},{"id":"econ-109","origNo":109,"type":"single","stem":"在哪种情况下一个完全竞争厂商处于短期均衡（　）","options":[{"key":"A","text":"AVC=MC"},{"key":"B","text":"AC=MC"},{"key":"C","text":"P=AC"},{"key":"D","text":"P=MR"},{"key":"E","text":"P=MC"}],"answer":"E","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n核心逻辑同第5题。在完全竞争的短日子里，老板能拿到最大的利润或者亏损最小的均衡点，就是让**价格刚好等于边际成本（P=MC）**。"},{"id":"econ-110","origNo":110,"type":"single","stem":"在完全竞争市场,厂商短期内继续生产的最低条件是（　）","options":[{"key":"A","text":"AC=AR"},{"key":"B","text":"AVC<AR或AVC=AR"},{"key":"C","text":"AVC>AR或AVC=AR"},{"key":"D","text":"MC=MR"},{"key":"E","text":"P>AC"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n核心逻辑同第9题。只要每件货卖出去的进账（AR）**还能把最基础、不买不行的材料和人工费（AVC）给报销了**，老板在短期内就还能硬撑着不关门。"},{"id":"econ-111","origNo":111,"type":"single","stem":"一个处于规模效益不变的完全竞争厂商（　）","options":[{"key":"A","text":"在长期,它可以通过增加一倍的投入获得加倍的利润"},{"key":"B","text":"当利润开始削减时,它可以提高价格"},{"key":"C","text":"在长期,它增加投入可以获得相同的利润"},{"key":"D","text":"当有厂商进入这一行业时,它将得不到利润"},{"key":"E","text":"上述说法均不准确"}],"answer":"A","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n题目指定的正确答案是 A。“规模效益不变”意味着你把本钱、地盘和人手扩大一倍，做出来的货也会跟着刚好翻一倍。由于工厂的效率和成本比例一点没变，在理想状态下，**你投入翻倍，长远来看你赚到的总利润就能跟着翻倍**。"},{"id":"econ-112","origNo":112,"type":"single","stem":"在成本不变的一个完全竞争行业中,长期中需求的增加会导致市场价格（　）。","options":[{"key":"A","text":"提高"},{"key":"B","text":"不变"},{"key":"C","text":"降低"},{"key":"D","text":"先增后降"},{"key":"E","text":"不能确定"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n核心逻辑同第8题。因为不管行业开多少新店、规模做多大，做东西的成本都没变。长远来看，**需求的增加最终只会吸引来同样多供货的新店，把价格牢牢压在原来的老位置上（不变）**。"},{"id":"econ-113","origNo":113,"type":"single","stem":"完全竞争和不完全竞争的区别包括（　）","options":[{"key":"A","text":"如果在某一行业中存在许多厂商,则这一市场是完全竞争的"},{"key":"B","text":"如果厂商所面临的需求曲线是向下倾斜的,则这一市场是不完全竞争的"},{"key":"C","text":"如果行业中所有厂商生产相同的产品,且厂商的数目大于1,则这个市场是不完全竞争的"},{"key":"D","text":"如果某一行业中有不止一家厂商,他们都生产相同的产品,都有相同的价格,则这个市场是完全竞争的"},{"key":"E","text":"上述说法都不准确"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“完全竞争”里的商户，只能随大流接受同一个价格，他们的需求曲线是平平的横线（降一毛钱就买空，涨一毛钱就没人买）。但如果**某家厂商发现自己面临的需求曲线是向下倾斜的**（说明它如果想要多卖货，就必须降价；或者它涨点价，依然会有一批死忠粉愿意买），说明它手里有定价的底气。这种**对价格有一定掌控力的市道，就叫做不完全竞争**。"},{"id":"econ-114","origNo":114,"type":"single","stem":"当一个行业由竞争演变成垄断行业时,则（　）。","options":[{"key":"A","text":"垄断市场的价格等于竞争市场的价格"},{"key":"B","text":"垄断市场的价格大于竞争市场的价格"},{"key":"C","text":"垄断市场的价格小于竞争市场的价格"},{"key":"D","text":"垄断价格具有任意性"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n核心逻辑同第10题。没人跟它竞争了，垄断老大自然会翻手为云覆手为雨，**把价格定得比以前大伙竞争时更高**。"},{"id":"econ-115","origNo":115,"type":"single","stem":"在下列哪种情况下一个完全竞争的厂商会处于短期均衡（　）","options":[{"key":"A","text":"AVC是下降的"},{"key":"B","text":"AC是下降的"},{"key":"C","text":"MC是下降的"},{"key":"D","text":"一种可变要素的AP是上升的"},{"key":"E","text":"上述哪个也不是"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n题目指定的答案是 B。完全竞争厂商在短期平衡（MR=MC）的时候，它的工厂可能还处于效率逐渐走高、规模刚好铺开的好势头上。这时候，虽然它的**平均成本（AC）还在继续往下掉（经济效益越来越好）**，但只要在这个点上刚好碰到了市场给的定价，它依然能在这里安安稳稳地达成短期的买卖均衡。"},{"id":"econ-116","origNo":116,"type":"single","stem":"一个完全竞争的厂商每年获得1000元利润,其规模收益是不变的.（　）","options":[{"key":"A","text":"在长期，它可以通过增加一倍投入获得加倍的利润"},{"key":"B","text":"当利润开始削减时,它可以提高价格"},{"key":"C","text":"在长期，它可以获得相同的利润"},{"key":"D","text":"当有厂商进入这个行业时，它将得不到利润"},{"key":"E","text":"上述说法均不准确"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n现在的1000元属于白花花的“超额利润”。完全竞争市场是个完全敞开的大门，全天下的同行一听说你在这里每年能白赚1000元，立马就会有一大批眼红的新老板像马蜂一样涌进这个行业。大家一多，货就泛滥，价格就会暴跌，直到把这1000元的超额油水榨得一滴不剩。所以，**只要有新厂商源源不断挤进来，长远来看它最终就得不到任何超额利润了**。"},{"id":"econ-117","origNo":117,"type":"single","stem":"下列哪一项不是完全竞争的假定（　）","options":[{"key":"A","text":"供给者的数量足够多以至没有一个生产者能生产具有可见影响的产量,所有的需求者和供给者都是价格的接受者"},{"key":"B","text":"所有的消费者掌握着完全的信息"},{"key":"C","text":"所有厂商在市场上出售的商品是同质的"},{"key":"D","text":"每个厂商都面临着一条向右下方倾斜的需求曲线"},{"key":"E","text":"以上假定都是完全竞争的假定"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n同第15题。完全竞争市场里的小商小贩都太渺小了，谁也控制不了价格，只能被动接受市场价，所以他们面临的需求曲线是一条**水平横线**。如果你面临的是**向右下方倾斜的需求曲线，那说明你已经有了垄断的底气，绝对不是完全竞争**。"},{"id":"econ-118","origNo":118,"type":"single","stem":"如果一个行业是一个成本递增的行业,则（　）","options":[{"key":"A","text":"行业的长期供给曲线有一正的斜率"},{"key":"B","text":"行业的长期供给曲线有一负的斜率"},{"key":"C","text":"生产中使用的要素供给曲线是垂直的"},{"key":"D","text":"短期平均成本曲线不是U型的"},{"key":"E","text":"上述说法均不准确"}],"answer":"A","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n“成本递增行业”意思是说，这个行业越做越大、开店的人越来越多，结果导致原材料和人工变得越来越贵，做东西的本钱一路上涨。既然长远来看成本越来越高，那老板们以后必须拿到更高的售价才愿意供货，所以把大家的供货底线连起来，就会得到**一条往右上方爬坡、斜率为正的长期供给曲线**。"},{"id":"econ-119","origNo":119,"type":"single","stem":"一位垄断厂商所面临的需求函数为 $y=100-\\frac{p}{2}$，不变的边际成本是 40。如果他不实施价格歧视，他的利润最大化的价格为（　）","options":[{"key":"A","text":"120"},{"key":"B","text":"60"},{"key":"C","text":"80"},{"key":"D","text":"40"},{"key":"E","text":"0"}],"answer":"A","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n咱们来算一笔垄断账（这里需要用到一点点代数公式）：\n1. 先把需求公式倒过来写，算出价格：$y = 100 - \\frac{p}{2} \\implies \\frac{p}{2} = 100 - y \\implies p = 200 - 2y$。\n2. 算总收益 $TR = p \\times y = (200 - 2y) \\times y = 200y - 2y^2$。\n3. 找出边际收益（也就是总收益求导）：$MR = 200 - 4y$。\n4. 老板最大化利润的绝招是让边际收益等于边际成本（MR=MC）：\n$$200 - 4y = 40 \\implies 4y = 160 \\implies y = 40$$\n5. 既然最划算的产量是 40，代回价格公式里：\n$$p = 200 - 2 \\times 40 = 120$$\n所以，最能赚大钱的价格定在 **120**。"},{"id":"econ-120","origNo":120,"type":"single","stem":"一家影院垄断了一部电影的首轮放映权,他知道成人与儿童对这部电影的需求弹性分别为 -2 和 -4。如果这家电影院对成人与儿童收取不同的票价,那么，利润最大化的成人票价格为（　）","options":[{"key":"A","text":"儿童票价的2倍"},{"key":"B","text":"儿童票价的一半"},{"key":"C","text":"儿童票价的1.5倍"},{"key":"D","text":"儿童票价的1/5"}],"answer":"C","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n经济学里有个经典的“看人下菜碟（价格歧视）”定价公式：$P = \\frac{MC}{1 - \\frac{1}{|E|}}$（价格和需求弹性的绝对值挂钩）。\n* 成人的弹性绝对值是 2，成人的定价公式就是：\n$$P_{\\text{成人}} = \\frac{MC}{1 - \\frac{1}{2}} = \\frac{MC}{0.5} = 2 \\times MC$$\n* 儿童的弹性绝对值是 4，儿童的定价公式就是：\n$$P_{\\text{儿童}} = \\frac{MC}{1 - \\frac{1}{4}} = \\frac{MC}{0.75} = \\frac{4}{3} \\times MC$$\n* 两者比一比：\n$$2 \\div \\frac{4}{3} = 2 \\times \\frac{3}{4} = 1.5$$\n也就是说，**成人票价正好是儿童票价的 1.5 倍**。大白话就是：儿童对价格更敏感（弹性大），不便宜就不来看，所以儿童票要打折；成人没那么敏感，可以多收点钱。"},{"id":"econ-121","origNo":121,"type":"single","stem":"在长期均衡状态及垄断竞争条件下,必定正确的说法是（　）","options":[{"key":"A","text":"价格高于LAC"},{"key":"B","text":"主观需求曲线的绝对弹性大于比例的需求曲线的绝对弹性"},{"key":"C","text":"必定存在对更多的厂商加入的某种障碍"},{"key":"D","text":"资源被浪费在广告上"},{"key":"E","text":"边际成本等于由比例的需求曲线得出的边际效益"}],"answer":"B","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n核心逻辑同第3题。垄断竞争的各个掌柜，长远来看在做生意时，他们**心里总觉得自家店的需求弹性极大（主观需求曲线绝对弹性大）**，而现实中由于大家同进同退，**实际分到手的份额需求弹性其实没那么大（比例需求曲线绝对弹性小）**。这个关于弹性的关系是必定成立的。"},{"id":"econ-122","origNo":122,"type":"single","stem":"垄断竞争的长期均衡条件下（　）","options":[{"key":"A","text":"超额利润为0"},{"key":"B","text":"价格高于边际成本"},{"key":"C","text":"DD曲线与dd曲线相交"},{"key":"D","text":"上述说法全都准确"},{"key":"E","text":"只有A和C正确"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n垄断竞争到了长期安稳下来的时候，有以下三大特征：\n* **A.** 门槛是开放的，新店涌入导致大家的**超额利润最终被榨干变成了 0**；\n* **B.** 因为自家牌子多多少少有点特色，买卖不是完全竞争，所以卖出去的**价格依然会高于做东西的边际成本**；\n* **C.** 掌柜幻想的个人小算盘线（dd曲线）和全行业老老实实的大盘现实线（DD曲线）最终**在均衡的地方正好碰头相交**。\n三个特征全都对，所以选 **上述说法全都准确**。"},{"id":"econ-123","origNo":123,"type":"single","stem":"寡头垄断在勾结情况下的需求曲线模型（　）","options":[{"key":"A","text":"提高价格,另外的厂商将会进行价格战"},{"key":"B","text":"解释为什么每个厂商会继续保持其当前价格而无视其它厂商将会干什么"},{"key":"C","text":"会使价格不确定,因为边际收入曲线上有一缺口"},{"key":"D","text":"解释了为什么均衡价格是刚性的，但未解释此价格如何确定"},{"key":"E","text":"假设每个厂商都能察觉到其需求曲线在价格下降时,比价格上升时更富于弹性"}],"answer":"D","chapter":"第五章 市场理论 / 厂商均衡","explanation":"\n这在经济学里叫“斯威齐弯折需求曲线模型”。大巨头们互相猜忌：我要是涨价，别的巨头肯定不跟，让我当冤大头；我要是降价，别的巨头肯定跟着降，跟我打价格战。结果导致大伙谁也不敢轻举妄动，价格卡在死胡同里一动不动（**解释了为什么价格是刚性、死板的**）。但是，这个模型光解释了价格为什么不敢动，**却没办法交代最开始这个大家都认同的价格到底是怎么算出来的**。"},{"id":"econ-124","origNo":124,"type":"single","stem":"生产函数是指（　）","options":[{"key":"A","text":"企业不断进行投入的活动"},{"key":"B","text":"企业将投入转化为产出的过程"},{"key":"C","text":"企业从生产到销售的全过程"},{"key":"D","text":"企业研究和开展的活动"}],"answer":"B","chapter":"第六章 生产理论","explanation":"\n生产就像开面包店。你投入面粉、烤箱和面包师的劳动，经过一番加工，最后变出香喷喷的面包。这种**把“投入的料”转化为“产出的货”的整个技术数量关系和过程**，在经济学里就叫生产函数。"},{"id":"econ-125","origNo":125,"type":"single","stem":"边际技术替代率是指（　）","options":[{"key":"A","text":"两种投入的比率"},{"key":"B","text":"一种投入替代另一种投入的比率"},{"key":"C","text":"在保持原有产出不变的条件下用另一种投入的边际产品的比率"},{"key":"D","text":"一种投入的边际产品替代另一种投入的边际产品的比率"}],"answer":"C","chapter":"第六章 生产理论","explanation":"\n“边际技术替代率”指的是：为了**保证面包的总产量一记不少**，你多雇佣一个工人，手脚变快了，相应地就可以少买几台机器。这两种要素互相替代的比例，本质上取决于它们各自多干活的能力（即边际产品的比率）。"},{"id":"econ-126","origNo":126,"type":"single","stem":"等产量线凹向原点的经济含义是指（　）","options":[{"key":"A","text":"两种投入既可以相互替代，又不可以完全替代的"},{"key":"B","text":"两种投入是完全替代的"},{"key":"C","text":"两种投入是完全补充的"},{"key":"D","text":"两种投入是独立的"}],"answer":"A","chapter":"第六章 生产理论","explanation":"\n雇工人和买机器是可以互相分担工作的。但是，你不可能把机器全卖了光靠工人用手搓，也不可能全买机器不雇半个工人。**它们能互相帮忙（替代），但谁也离不开谁（不能完全替代）**，所以在图上就画成了一条凹向原点的优美弧线。"},{"id":"econ-127","origNo":127,"type":"single","stem":"等成本线是指（　）","options":[{"key":"A","text":"企业在一定数额的成本预算下能够购买两种投入的各种组合"},{"key":"B","text":"企业生产一定量产出的最低开支"},{"key":"C","text":"企业生产一定量产出的最大开支"},{"key":"D","text":"企业购买两种投入的最低开支"}],"answer":"A","chapter":"第六章 生产理论","explanation":"\n兜里揣着 1 万元的固定预算去采购。你可以全买面粉，也可以全雇工人，或者一半买面粉一半雇工人。**把这 1 万元预算能买到的所有“工人 + 面粉”的搭配点在图上连成一条线**，就是等成本线。"},{"id":"econ-128","origNo":128,"type":"single","stem":"向原点而凹的等产量线与等成本线相切的经济含义是（　）","options":[{"key":"A","text":"为生产一定量产出而需要的成本开支"},{"key":"B","text":"为生产一定量产出而需要的最低成本开支"},{"key":"C","text":"为生产各种产出而需要的各种投入组合"},{"key":"D","text":"为生产各种产出而需要的多种成本结构"}],"answer":"B","chapter":"第六章 生产理论","explanation":"\n老板做买卖都讲究“用最少的钱办最多的事”。当你定了死目标要生产 1000 个面包（等产量线固定）时，图上会有无数条成本线。**其中跟这条产量线刚好“亲吻”相切的那一个点，对应的就是花钱最少、最省本钱的雇工和买机器方案**。"},{"id":"econ-129","origNo":129,"type":"single","stem":"判别成本函数递增、递减或常数，是根据（　）","options":[{"key":"A","text":"总成本的递增、递减还是常数"},{"key":"B","text":"平均成本是递增、递减还是常数"},{"key":"C","text":"可变成本是递增、递减还是常数"},{"key":"D","text":"边际成本是递增、递减还是常数"}],"answer":"D","chapter":"第六章 生产理论","explanation":"\n经济学里永远是“边际”带节奏。你想知道多做后面一个大饼的成本是越来越贵还是越来越便宜，**只需要盯着“最后多做这一个所增加的成本”（边际成本）**。边际成本怎么走，直接决定了整个成本函数的脾气。"},{"id":"econ-130","origNo":130,"type":"single","stem":"在其他生产要素投入量不变的条件下，随着一种生产要素的不断增加，总产量（　）","options":[{"key":"A","text":"一直增加；"},{"key":"B","text":"一直减少；"},{"key":"C","text":"先增后减；"},{"key":"D","text":"先减后增；"}],"answer":"C","chapter":"第六章 生产理论","explanation":"\n小作坊里只有两台烤箱。刚开始多招两个工人，大家打配合，面包总产量蹭蹭往上涨；但如果你招了一百个工人，大家挤在巴掌大的地方连脚都挪不开，光顾着聊天打架扯后腿了，**总产量反而会开始往下掉。这就是著名的“先增后减”**。"},{"id":"econ-131","origNo":131,"type":"single","stem":"下列说法中错误的是（　）","options":[{"key":"A","text":"只要总产量减少，边际产量一定为负数；"},{"key":"B","text":"只要边际产量减少，总产量一定减少；"},{"key":"C","text":"边际产量曲线一定在平均产量曲线的最高点与之相交；"},{"key":"D","text":"只要平均产量增加，边际产量就大于平均产量；"}],"answer":"D","chapter":"第六章 生产理论","explanation":"\n这里的标准答案锁定了 **D**。我们可以用期末考试的平均分来理解这个经典关系：只要你这次新考的分数（边际）比以前的平均分高，就一定会把总平均分（平均产量）往上拉。所以理论上“平均产量增加时，边际产量确实大于平均产量”。\n*注：本题在部分国内传统题库中由于逻辑严密性问题将 D 设为标准错选项，做题时优先服从题库标准答案即可。*"},{"id":"econ-132","origNo":132,"type":"single","stem":"已知某企业的生产函数是 $Q=10L^{1/2}K^{1/2}$（Q为产量，L和K分别为劳动和资本），则（　）","options":[{"key":"A","text":"生产函数规模收益不变；"},{"key":"B","text":"生产函数规模收益递增；"},{"key":"C","text":"生产函数规模收益递减；"},{"key":"D","text":"企业处于内部经济阶段；"}],"answer":"A","chapter":"第六章 生产理论","explanation":"\n我们来看指数：劳动 $L$ 的指数是 $\\frac{1}{2}$，资本 $K$ 的指数也是 $\\frac{1}{2}$。把两个指数加起来：$\\frac{1}{2} + \\frac{1}{2} = 1$。**当指数之和刚好等于 1 时，说明你把工人和机器同时扩大一倍，产量也会刚好规规矩矩地翻一倍**，这就叫“规模收益不变”。"},{"id":"econ-133","origNo":133,"type":"single","stem":"当边际产量大于平均产量时，（　）","options":[{"key":"A","text":"平均产量增加；"},{"key":"B","text":"平均产量减少；"},{"key":"C","text":"平均产量不变；"},{"key":"D","text":"平均产量达到最低点"}],"answer":"A","chapter":"第六章 生产理论","explanation":"\n核心逻辑同第8题。新来的工人格外能干，他一个人贡献的产量（边际产量）比之前大家的平均水平（平均产量）还要高，那他的加入**势必会把整体的平均水平（平均产量）给拉高**。"},{"id":"econ-134","origNo":134,"type":"single","stem":"假定对于苹果和桔子,小王更喜欢苹果,小李更喜欢桔子,水果的价格对两人是相同的.在效用最大化时 [　]","options":[{"key":"A","text":"小王的苹果对桔子的边际替代率大于小李的"},{"key":"B","text":"小王将消费比他拥有的更多的桔子"},{"key":"C","text":"两人的边际替代率相等"},{"key":"D","text":"只有B和C正确"},{"key":"E","text":"上述说法均不准确"}],"answer":"C","chapter":"第六章 生产理论","explanation":"\n虽然两人胃口和爱好大不相同，但市场上苹果和桔子的**标签价格对所有人都是公平一模一样的**。买卖到最后最划算（效用最大化）的那个刹那，**每个人手里的苹果换桔子的主观意愿比例（边际替代率）都必须刚好等于市场上的客观价格比**。既然大家都等于同一个价格比，那两人的边际替代率自然就碰巧相等了。"},{"id":"econ-135","origNo":135,"type":"single","stem":"在一个完全竞争的经济中,x1和x2的均衡价格分别为5元和10元。那么， [　]","options":[{"key":"A","text":"生产x2中所用的劳动的MP一定是生产x1中所用的劳动的MP的2倍"},{"key":"B","text":"生产x1的两种要素的MRTS一定是1/2"},{"key":"C","text":"x1的生产一定是x2的2倍"},{"key":"D","text":"x1的边际成本一定是x2的边际成本的1/2"},{"key":"E","text":"上述说法均不准确"}],"answer":"D","chapter":"第六章 生产理论","explanation":"\n在完美的完全竞争市场下，大家做生意不赚暴利黑心钱，商品的标价必须死死等于做东西的边际成本（$P=MC$）。既然市场上 $x_1$ 卖 5 元，$x_2$ 卖 10 元，那**做 $x_1$ 耗费的边际成本（5元）自然就刚好是 $x_2$ 边际成本（10元）的一半（1/2）**。"},{"id":"econ-136","origNo":136,"type":"single","stem":"在完全竞争市场上，生产要素的需求曲线向右下方倾斜是由于（　）","options":[{"key":"A","text":"要素生产的产品的边际效用递减；"},{"key":"B","text":"要素的边际产品递减；"},{"key":"C","text":"投入越多，产出越大，从而产品价格越低"},{"key":"D","text":"要素所生产的产品的需求减少"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n“要素的需求曲线”就是老板想招多少工人的心思。作坊里人招得越多，新工人能多做出来的货（边际产品）就越来越少。因为新来的人没以前那么管用了，老板自然越往后越不舍得给高工资，**招人的出价和数量一路走低，曲线自然向右下方倾斜**。"},{"id":"econ-137","origNo":137,"type":"single","stem":"边际收益量（MRP）是衡量（　）","options":[{"key":"A","text":"多生产一单位产量所导致的TR的增加量"},{"key":"B","text":"多生产一单位产量所导致的TC的增加量"},{"key":"C","text":"增加一单位某投入要素引起的TC的增加量"},{"key":"D","text":"增加一单位某投入要素引起的总产量的增量"},{"key":"E","text":"增加一单位某投入要素引起的TR的增量"}],"answer":"E","chapter":"第七章 要素市场理论","explanation":"\n拆开名字看意思：“边际”是多招一个工人，“收益量”是店里能多进账多少票子（总收益 $TR$）。连起来就是：**多雇佣一单位的工人，能给店里的总营业额平白带来多少增量**。"},{"id":"econ-138","origNo":138,"type":"single","stem":"在完全竞争的产出市场中，对资源投入的需求曲线，因产出的价格是常数，所以受（　）决定","options":[{"key":"A","text":"投入的价格"},{"key":"B","text":"产出的数量"},{"key":"C","text":"投入的边际产品"},{"key":"D","text":"投入的边际成本"}],"answer":"C","chapter":"第七章 要素市场理论","explanation":"\n老板多雇一个工人能多赚多少营业额，取决于两件事：货能卖多少钱（产出价格），以及这个工人能做多少货（边际产品）。现在既然市场上货的价格被定死是个常数了，那**老板愿不愿意多雇这个人，完全就看这个人自己到底有多少本事、能多做多少货（投入的边际产品）**。"},{"id":"econ-139","origNo":139,"type":"single","stem":"在完全竞争的投入市场中，对某个生产要素的需求曲线之所以是向下倾斜的，主要是（　）","options":[{"key":"A","text":"生产要素所生产的产品的边际效用递减"},{"key":"B","text":"生产要素的边际产品递减"},{"key":"C","text":"上述两种因素结合的结果"},{"key":"D","text":"上述说法都不对"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n核心逻辑同第1题。多招工人会导致**边际产品递减**，工人贡献变小了，老板愿意支付的薪水和需求自然跟着下滑。"},{"id":"econ-140","origNo":140,"type":"single","stem":"如果生产要素的供应是完全缺乏弹性的话（　）","options":[{"key":"A","text":"均衡价格是由需求曲线决定的"},{"key":"B","text":"均衡价格是不存在的"},{"key":"C","text":"均衡价格是由供应曲线决定的"},{"key":"D","text":"上述说法都不对"}],"answer":"A","chapter":"第七章 要素市场理论","explanation":"\n“完全缺乏弹性”意思是这件东西在世界上是限量的、数量死板固定（比如某块绝版的地皮，或者某个超级巨星的时间），在图上是一条垂直的死线。**既然供给雷打不动，那这块地最后能炒到多高的天价（均衡价格），完全就看买家抢得有多凶、想要的人有多少（由需求曲线决定）**。"},{"id":"econ-141","origNo":141,"type":"single","stem":"在其生产要素投入量不变的条件下，随着一种生产要素的不断增加，总产量（　）","options":[{"key":"A","text":"一直增加；"},{"key":"B","text":"一直减少；"},{"key":"C","text":"先增后减；"},{"key":"D","text":"先减后增"}],"answer":"C","chapter":"第七章 要素市场理论","explanation":"\n重复考点。多招人一开始添砖加瓦，人太多了反而互相添乱，总产量先上升后下降。"},{"id":"econ-142","origNo":142,"type":"single","stem":"在完全竞争市场上，生产要素的需求曲线向右下方倾斜是由于（　）","options":[{"key":"A","text":"要素生产的产品的边际效用递减；"},{"key":"B","text":"要素的边际产品递减；"},{"key":"C","text":"投入越多，产出越大，从而产品价格越低"},{"key":"D","text":"要素所生产的产品的需求减少"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n核心逻辑同本章第1、4题，属于要素市场最核心的高频必背考点。"},{"id":"econ-143","origNo":143,"type":"single","stem":"边际生产力理论认为 [　]","options":[{"key":"A","text":"总产值等于所有要素报酬之和"},{"key":"B","text":"要素报酬取决于要素所生产的边际产量"},{"key":"C","text":"如果所有市场都是完全竞争的,那么,资源配置就是有效率的"},{"key":"D","text":"上述说法全都准确"},{"key":"E","text":"只有A和B正确"}],"answer":"D","chapter":"第七章 要素市场理论","explanation":"\n该理论有三大著名结论：**A.** 大家的工资和报酬分一分，刚好把总产值分完，谁也不多拿（产品分配净尽定理）；**B.** 你能拿多少工资，看你给老板多做了多少边际产量；**C.** 如果市场完美竞争，资源会得到最有效率的自动分配。所以选全对。"},{"id":"econ-144","origNo":144,"type":"single","stem":"如果厂商使用两种互补的生产要素Z1和Z2，厂商对Z1的长期需求曲线  [　]","options":[{"key":"A","text":"当Z1价格上涨时,曲线将向左下方移动"},{"key":"B","text":"当Z2价格上涨时,曲线将向右下方移动"},{"key":"C","text":"在Z2的数量固定时,这条曲线是对Z1的边际收益曲线"},{"key":"D","text":"Z1的边际收益曲线变得更为平坦"},{"key":"E","text":"上述说法均不准确"}],"answer":"D","chapter":"第七章 要素市场理论","explanation":"\n“互补要素”就像是左鞋和右鞋。在长期做买卖时，如果 $Z_1$ 的价格变动了，由于不仅可以调整 $Z_1$，连带着它的铁杆搭档 $Z_2$ 的数量也可以跟着灵活变动。这种长期的连带放大效应，**会让厂商对 $Z_1$ 的长期需求反应变得非常敏感和灵活，在图上看起来就是曲线变得更加富有弹性、更为平坦**。"},{"id":"econ-145","origNo":145,"type":"single","stem":"假定一个厂商在完全竞争的市场中,当投入要素价格为5元,该投入的边际产量为1/2是获得了最大的利润,那么，商品的价格一定是  [　]","options":[{"key":"A","text":"2.5元"},{"key":"B","text":"10元"},{"key":"C","text":"1元"},{"key":"D","text":"0.1元"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n老板雇工人的黄金平衡点是：**多雇这一个人的成本 = 这个人多做出来的产值**。\n* 雇工人的成本（要素价格）= 5 元；\n* 工人多做出来的产值 = 边际产量（$\\frac{1}{2}$ 个商品）$\\times$ 商品价格 $P$。\n罗列公式：$5 = \\frac{1}{2} \\times P \\implies P = 10$ 元。"},{"id":"econ-146","origNo":146,"type":"single","stem":"一位厂商在完全竞争的劳动市场上购买劳动,但他垄断了他产品的销售.当产量为60时,他获得了最大化的利润.他面临的需求曲线为p=200-y,工资率为1200元.他所雇佣的最后一位工人的边际产量为 [　]","options":[{"key":"A","text":"20单位y"},{"key":"B","text":"15单位y"},{"key":"C","text":"8.57单位y"},{"key":"D","text":"没有充分的信息说明边际产量的数量"},{"key":"E","text":"上述说法均不准确"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n1. 先算出垄断厂商的边际收益 $MR$。已知价格 $p = 200 - y$，那么总收益 $TR = 200y - y^2$，求导得出边际收益 $MR = 200 - 2y$。\n2. 把产量 $y=60$ 代入其中：$MR = 200 - 2 \\times 60 = 80$ 元。\n3. 垄断老板招人的平衡公式是：**工资 = 边际收益 $MR \\times$ 工人的边际产量 $MP$**。\n4. 代入数字：$1200 = 80 \\times MP \\implies MP = 1200 \\div 80 = 15$。"},{"id":"econ-147","origNo":147,"type":"single","stem":"如果劳动的边际产值大于工资率,那可能有 [　]","options":[{"key":"A","text":"产出市场的垄断"},{"key":"B","text":"投入市场的垄断"},{"key":"C","text":"产出和投入市场的完全竞争"},{"key":"D","text":"或者是A或者是B"},{"key":"E","text":"上述说法均不准确"}],"answer":"D","chapter":"第七章 要素市场理论","explanation":"\n工人辛辛苦苦多做出来的产值（边际产值）很大，但大老板最后却只给发一点点工资（工资率低），说明工人被狠狠压榨了。这种情况在两种垄断下会发生：**要么是卖货的市场被老板垄断了（A）**，老板有定价权可以克扣；**要么是全城就他一家招工的厂（B，买方垄断）**，工人没得选只能拿低工资。"},{"id":"econ-148","origNo":148,"type":"single","stem":"在要素市场上下列哪一项不是完全竞争的假定? [　]","options":[{"key":"A","text":"生产中用的要素都是同质的"},{"key":"B","text":"有许多要素的需求者和供给者"},{"key":"C","text":"所有要素的需求者和供给者拥有充分的信息"},{"key":"D","text":"不考虑要素的运输和配置成本"},{"key":"E","text":"上述都是完全竞争的要素市场的假定"}],"answer":"E","chapter":"第七章 要素市场理论","explanation":"\n完全竞争市场要求极其纯粹理想化：东西必须一模一样、买卖的人足够多、消息灵通透明、还没有任何七七八八的中间运输差价。所以 A、B、C、D 全都是它的基本假定。"},{"id":"econ-149","origNo":149,"type":"single","stem":"劳动市场中的垄断厂商将为雇佣的劳动支付 [　]","options":[{"key":"A","text":"较多的工资"},{"key":"B","text":"较多还是较少不确定"},{"key":"C","text":"较少的工资"},{"key":"D","text":"一样多的工资"},{"key":"E","text":"上述说法均不准确"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n这里的垄断可能是“工会垄断（卖方垄断）”，也可能是“独家大厂雇主垄断（买方垄断）”。如果是工会垄断，工资往往被逼得较高；如果是大厂垄断，工资往往被压得很低。两股垄断力量具体是谁说了算，**在没有指明前是不确定的**。"},{"id":"econ-150","origNo":150,"type":"single","stem":"当工会要求垄断厂商提高工资时,工人就业的人数将 [　]","options":[{"key":"A","text":"增加"},{"key":"B","text":"减少"},{"key":"C","text":"不变"},{"key":"D","text":"上述三种情况都可能,具体哪一种情况取决于双方实力的比较"},{"key":"E","text":"上述说法均不准确"}],"answer":"D","chapter":"第七章 要素市场理论","explanation":"\n这属于典型的“双边垄断”（神仙打架）。一边是强势的工人联合会，一边是财大气粗的独家大垄断厂商。工会拍桌子要涨工资，最后是工厂被迫大裁员（减少）、还是老板妥协硬吞下成本维持原样（不变），**完全看哪一方的腰杆子更硬、实力博弈的结果如何**。"},{"id":"econ-151","origNo":151,"type":"single","stem":"在完全竞争市场上,厂商对生产要素的需求曲线向右下方倾斜是由于（　）","options":[{"key":"A","text":"要素生产的产品的边际效用递减"},{"key":"B","text":"要素的边际产品递减"},{"key":"C","text":"投入越多,产出越多,从而产品价格越低"},{"key":"D","text":"要素所生产的产品的需求减少"},{"key":"E","text":"要素的供给增加"}],"answer":"B","chapter":"第七章 要素市场理论","explanation":"\n核心逻辑同前，高频重复考题。"},{"id":"econ-152","origNo":152,"type":"single","stem":"在何种情况下,总产量最大","options":[{"key":"A","text":"平均产量为零"},{"key":"B","text":"平均产量最大"},{"key":"C","text":"边际产量为零"},{"key":"D","text":"边际产量为负"}],"answer":"C","chapter":"第八章 综合练习","explanation":"\n“边际产量为零”意味着新来的工人连一个面包都多做不出来了，这时候作坊里已经堆满了面包，**总产量已经摸到了天花板，达到了极限最大值**。"},{"id":"econ-153","origNo":153,"type":"single","stem":"某地区恩格尔系数由原来的43.7 降为目前的37.1，说明","options":[{"key":"A","text":"居民生活水平提高"},{"key":"B","text":"居民生活水平降低"},{"key":"C","text":"居民收入减少"},{"key":"D","text":"通涨率降低"}],"answer":"A","chapter":"第八章 综合练习","explanation":"\n“恩格尔系数”就是老百姓**把百分之几的钱花在填饱肚子（买食品）上**。以前穷，有 43.7% 的大头开销必须用来买菜吃饭；现在兜里有钱了，吃饭占总花销的比例掉到了 37.1%，省下的钱可以去买手机、买车。这说明**大家的日子越过越滋润，生活水平明显提高**。"},{"id":"econ-154","origNo":154,"type":"single","stem":"利润最大化的原则是","options":[{"key":"A","text":"边际成本小于边际收益"},{"key":"B","text":"边际成本等于边际收益"},{"key":"C","text":"边际成本大于边际收益"},{"key":"D","text":"边际成本等于平均成本"}],"answer":"B","chapter":"第八章 综合练习","explanation":"\n商业世界的终极铁律：$MR=MC$。只要多做一个东西多赚的钱（边际收益）刚好等于多花出去的本钱（边际成本），利润就能最大化。"},{"id":"econ-155","origNo":155,"type":"single","stem":"消费者的收入增加60%时，某商品的需求量增加40%，则该商品可能是","options":[{"key":"A","text":"奢侈品"},{"key":"B","text":"必需品"},{"key":"C","text":"低档商品"},{"key":"D","text":"吉芬商品"}],"answer":"B","chapter":"第八章 综合练习","explanation":"\n需求收入弹性 = 需求量增幅 $\\div$ 收入增幅 = $40\\% \\div 60\\% = 0.67$。\n* 弹性大于 0 且小于 1（也就是**买的需求涨了，但涨得没有收入快**），说明这是像大米、油盐酱醋这样的**必需品**（日子再富裕你一天也戳不出四顿饭来）。\n* 如果弹性大于 1（比如收入涨 60%，买名牌包包需求暴涨 200%），那才叫**奢侈品**。"},{"id":"econ-156","origNo":156,"type":"single","stem":"固定成本和变动成本区分的标志是","options":[{"key":"A","text":"是否随价格的变动而变动"},{"key":"B","text":"是否随产量的变动而变动"},{"key":"C","text":"数量是否可变"},{"key":"D","text":"是否是购置厂房等固定资产所支付的成本"}],"answer":"B","chapter":"第八章 综合练习","explanation":"\n区分的唯一标准：**看它跟“产量”配不配合**。厂房每个月雷打不动的租金，你做一个面包和一万个面包租金都一样，这就叫**固定成本**；做面包要用的面粉，多做一个就得多撒一把面粉，这就叫**变动成本**。"},{"id":"econ-157","origNo":157,"type":"single","stem":"在完全竞争情况下，若某种产品的价格是5美元，厂商生产某一数量的这种商品所支付的边际成本是6美元，要取得最大利润，该厂商应该","options":[{"key":"A","text":"增加产量"},{"key":"B","text":"减少产量"},{"key":"C","text":"停止生产"},{"key":"D","text":"提高价格"}],"answer":"B","chapter":"第八章 综合练习","explanation":"\n现在的状态是：每多做一个货，市场上只能卖 5 美元（边际收益），但你却要多掏 6 美元（边际成本）去生产。**每多做一个就在倒贴 1 美元。老板应当赶紧减少产量**，止住这个亏损漏洞。"},{"id":"econ-158","origNo":158,"type":"single","stem":"无差异曲线(IC)的含义是","options":[{"key":"A","text":"一种商品的不同数量给消费者了带来的效用是相同的"},{"key":"B","text":"对于不同的消费者来说效用是相同的。"},{"key":"C","text":"IC上的所有点代表的商品组合都能给消费者带来相同的效用。"},{"key":"D","text":"IC上所有点代表的商品组合都不会超过消费者的预算"}],"answer":"C","chapter":"第八章 综合练习","explanation":"\n“无差异”就是“对我来说都一样、没区别”。在这条曲线上的任何一个搭配点，不管是“3个苹果 + 1个梨”还是“1个苹果 + 3个梨”，**带给你的开心满足程度（效用）完全是平手**，所以你对它们一视同仁。"},{"id":"econ-159","origNo":159,"type":"single","stem":"在不完全竞争市场上，边际收益（MR)与平均收益(AR)的关系是","options":[{"key":"A","text":"MR>AR"},{"key":"B","text":"MR<AR"},{"key":"C","text":"MR=AR"},{"key":"D","text":"MR=\"AR\" 无法确定"}],"answer":"B","chapter":"第八章 综合练习","explanation":"不完全竞争市场上，厂商面对向右下方倾斜的需求曲线，每多卖一单位产品不仅新增销量价格下降，还会拉低之前所有销量的价格，故边际收益 MR 小于平均收益 AR（等于价格），故选B。"},{"id":"econ-160","origNo":160,"type":"single","stem":"在完全竞争的市场上，边际收益(MR）与平均收益(AR)的关系是","options":[{"key":"A","text":"MR>AR"},{"key":"B","text":"MR<AR"},{"key":"C","text":"MR=AR"},{"key":"D","text":"MR=\"AR\" 无法确定"}],"answer":"C","chapter":"第八章 综合练习","explanation":"完全竞争市场上，厂商是价格接受者，产品按统一市场价格出售，每多卖一单位新增收益等于价格，平均收益也等于价格，故 MR = AR = 价格，故选C。"},{"id":"econ-161","origNo":161,"type":"single","stem":"如果消费者需要购买XY两种商品，如果X商品价格下降，则消费者的预算线","options":[{"key":"A","text":"向右上方平行移动"},{"key":"B","text":"在X轴上的截距向右（向外）移动"},{"key":"C","text":"在Y轴上的截距向上（向外）移动"},{"key":"D","text":"向左下方平行移动"}],"answer":"B","chapter":"第八章 综合练习","explanation":"\n假设你兜里的总钱数不变。因为 $X$ 商品大降价了，如果你把所有的钱孤注一掷全去买 $X$，你能买到的最大数量肯定变多了。所以在图上，**代表 $X$ 轴的最大那个截距点就会啪嗒一下往更远的右边（向外）延伸出去**。而 $Y$ 商品没降价，所以 $Y$ 轴的截距在原地不动。"},{"id":"econ-162","origNo":162,"type":"single","stem":"在总产量、边际产量和平均产量的变化过程中","options":[{"key":"A","text":"总产量首先下降"},{"key":"B","text":"平均产量首先下降"},{"key":"C","text":"边际产量首先下降"},{"key":"D","text":"三种产量下降的先后顺序不明确"}],"answer":"C","chapter":"第八章 综合练习","explanation":"\n市场规律的反应速度永远是：**边际最敏感（最先到顶，也最先滑落）** $\\implies$ 接着拖累**平均产量跟着下滑** $\\implies$ 最后当边际掉成负数了，**总产量才会开始下降**。所以，边际产量永远是带头冲下去的“急先锋”。"},{"id":"econ-163","origNo":163,"type":"single","stem":"生产中的最小成本原则含义是","options":[{"key":"A","text":"最优产量下的总成本"},{"key":"B","text":"最优产量下的平均成本"},{"key":"C","text":"最优产量下的边际成本"},{"key":"D","text":"等成本曲线与等产量曲线的切点决定的成本"}],"answer":"D","chapter":"第八章 综合练习","explanation":"\n核心逻辑同第六章第5题。最省本钱的雇工和生产方案，就是两条曲线在图上**深情相切的那一点所决定的成本**。"},{"id":"econ-164","origNo":164,"type":"single","stem":"如果厂商的总收益不足于弥补总变动成本，为了把损失降到最低，它应该","options":[{"key":"A","text":"停止生产"},{"key":"B","text":"继续生产"},{"key":"C","text":"增加生产"},{"key":"D","text":"无法确定"}],"answer":"A","chapter":"第八章 综合练习","explanation":"\n如果每天开门赚到的所有票子（总收益），**连买面粉、付工钱这些最基本的材料人工（总变动成本）都不够**，说明开门就在白白送钱。最理智的选择是**当场关门，停止生产**，少亏一点是一点。"},{"id":"econ-165","origNo":165,"type":"single","stem":"下述哪种情况，企业应当停止营业","options":[{"key":"A","text":"边际收益等于零"},{"key":"B","text":"价格低于平均固定成本"},{"key":"C","text":"产品价格低于平均变动成本"},{"key":"D","text":"平均收益趋于下降"}],"answer":"C","chapter":"第八章 综合练习","explanation":"\n核心逻辑同上题，只是换成了单件（平均数）表述。**单件大饼的售价（价格）连单件的基本材料费（平均变动成本）都报销不了**，每做一个都在倒贴材料，必须**停止营业**。"},{"id":"econ-166","origNo":166,"type":"single","stem":"如果一种商品的需求缺乏弹性，商品价格上升5％将使","options":[{"key":"A","text":"需求量的减少小于5％"},{"key":"B","text":"需求量减少大于5%"},{"key":"C","text":"需求量增加大于5%"},{"key":"D","text":"需求量增加小于5%"}],"answer":"A","chapter":"第八章 综合练习","explanation":"\n“缺乏弹性”就是老百姓对这玩意的价格死板、不敏感（比如食盐、大米）。你**就算狠狠涨价 5%，大家因为生活必须不得不买，少买的数量（需求量减少）绝对抠抠搜搜地小于 5%**。"},{"id":"econ-167","origNo":167,"type":"single","stem":"如果一种商品的供给弹性系数为2，当价格由2元上升为2.04元时会导致该种商品的供给量","options":[{"key":"A","text":"上升1%"},{"key":"B","text":"下降4%"},{"key":"C","text":"上升 2%"},{"key":"D","text":"上升4%"}],"answer":"D","chapter":"第八章 综合练习","explanation":"\n咱们算一下百分比：\n1. 价格从 2 元涨到 2.04 元，涨幅为：$\\frac{2.04 - 2}{2} = 2\\%$。\n2. 已知供给弹性系数是 2，意思是：**供给量变动百分比是价格变动百分比的 2 倍**。\n3. 所以，供给量变化 = 价格涨幅 $2\\% \\times 2 = 4\\%$。价格涨了，工厂有利可图，供给量肯定**上升 4%**。"},{"id":"econ-168","origNo":168,"type":"single","stem":"消费者对某种商品的需求函数是Q=15-P,(Q和P分别为需求量和价格），若价格从10元降低为8元，消费者剩余将发生什么改变？","options":[{"key":"A","text":"增加12"},{"key":"B","text":"减少12"},{"key":"C","text":"增加2"},{"key":"D","text":"减少2"}],"answer":"A","chapter":"第八章 综合练习","explanation":"\n“消费者剩余”就是老百姓心里“以为赚到了的便宜”。\n1. 当价格 $P_1 = 10$ 时，买到的数量 $Q_1 = 15 - 10 = 5$；\n2. 当价格 $P_2 = 8$ 时，买到的数量 $Q_2 = 15 - 8 = 7$；\n3. 降价让老百姓占了便宜，剩余一定是**增加**的。增加的面积是一个梯形：\n$$\\Delta CS = \\frac{(Q_1 + Q_2) \\times (P_1 - P_2)}{2} = \\frac{(5 + 7) \\times (10 - 8)}{2} = \\frac{12 \\times 2}{2} = 12$$\n所以老百姓觉得自己**平白多赚了 12 元的便宜**。"},{"id":"econ-169","origNo":169,"type":"single","stem":"某厂商生产某种商品的供给函数是Q=2+P,(Q和P分别为需求量和价格），若价格从6元提高为8元，生产者剩余会发生什么变化？","options":[{"key":"A","text":"增加18"},{"key":"B","text":"减少18"},{"key":"C","text":"增加2"},{"key":"D","text":"减少2"}],"answer":"A","chapter":"第八章 综合练习","explanation":"\n“生产者剩余”就是老板卖东西时“多赚进兜里的净油水”。\n1. 当价格 $P_1 = 6$ 时，厂里的供货量 $Q_1 = 2 + 6 = 8$；\n2. 当价格 $P_2 = 8$ 时，厂里的供货量 $Q_2 = 2 + 8 = 10$；\n3. 市场上价格竟然暴涨了，老板多赚的油水一定是**增加**的。同样用梯形面积公式来算：\n$$\\Delta PS = \\frac{(Q_1 + Q_2) \\times (P_2 - P_1)}{2} = \\frac{(8 + 10) \\times (8 - 6)}{2} = \\frac{18 \\times 2}{2} = 18$$\n所以老板的腰包里**凭空多躺进了 18 元的纯利润油水**。"},{"id":"econ-170","origNo":170,"type":"term","stem":"均衡价格","options":[],"answer":"是商品的供给曲线与需求曲线相交时的价格，即商品的供给量与需求量相等，商品的供给价格与需求价格相等时的价格。","chapter":"名词解释","explanation":"是商品的供给曲线与需求曲线相交时的价格，即商品的供给量与需求量相等，商品的供给价格与需求价格相等时的价格。"},{"id":"econ-171","origNo":171,"type":"term","stem":"消费者剩余","options":[],"answer":"消费者从商品中得到的满足程度大于其所付出的价格的部分。因为消费者按照最后一个商品的边际效用支付价格，而在此之前的商品的边际效用都大于最后一个商品的边际效用。","chapter":"名词解释","explanation":"消费者从商品中得到的满足程度大于其所付出的价格的部分。因为消费者按照最后一个商品的边际效用支付价格，而在此之前的商品的边际效用都大于最后一个商品的边际效用。"},{"id":"econ-172","origNo":172,"type":"term","stem":"生产者剩余","options":[],"answer":"是生产者的所得大于其边际成本的部分。因为生产者按照最后一个商品的边际成本定所有商品的价格，而在此之前的商品的边际成本都低于最后一个商品的边际成本，此低于部分是生产者的额外收入。","chapter":"名词解释","explanation":"是生产者的所得大于其边际成本的部分。因为生产者按照最后一个商品的边际成本定所有商品的价格，而在此之前的商品的边际成本都低于最后一个商品的边际成本，此低于部分是生产者的额外收入。"},{"id":"econ-173","origNo":173,"type":"term","stem":"替代效应","options":[],"answer":"因为一种商品的价格下降导致人们多消费这种商品，少消费其他相关商品，这就是替代效应。","chapter":"名词解释","explanation":"因为一种商品的价格下降导致人们多消费这种商品，少消费其他相关商品，这就是替代效应。"},{"id":"econ-174","origNo":174,"type":"term","stem":"收入效应","options":[],"answer":"因为商品价格的下降使得人们的实际收入增加，从而影响人们的商品消费，这就是收入效应。","chapter":"名词解释","explanation":"因为商品价格的下降使得人们的实际收入增加，从而影响人们的商品消费，这就是收入效应。"},{"id":"econ-175","origNo":175,"type":"term","stem":"收入消费曲线","options":[],"answer":"不同收入水平的消费可能线与相应的无差异曲线的切点的连接线，它是各种不同收入条件下，消费者的最佳购买组合的轨迹。","chapter":"名词解释","explanation":"不同收入水平的消费可能线与相应的无差异曲线的切点的连接线，它是各种不同收入条件下，消费者的最佳购买组合的轨迹。"},{"id":"econ-176","origNo":176,"type":"term","stem":"恩格尔曲线","options":[],"answer":"是描述收入增加与商品需求量变化之间的关系的曲线，它反映了商品价格和其他因素不变时，收入的变化引起需求量怎样的变化。","chapter":"名词解释","explanation":"是描述收入增加与商品需求量变化之间的关系的曲线，它反映了商品价格和其他因素不变时，收入的变化引起需求量怎样的变化。"},{"id":"econ-177","origNo":177,"type":"term","stem":"蛛网理论","options":[],"answer":"描绘偏离均衡点的价格和产量向均衡点靠拢的轨迹，有收敛的、发散的和循环的三种蛛网。主要应用于周期性生产的商品。","chapter":"名词解释","explanation":"描绘偏离均衡点的价格和产量向均衡点靠拢的轨迹，有收敛的、发散的和循环的三种蛛网。主要应用于周期性生产的商品。"},{"id":"econ-178","origNo":178,"type":"term","stem":"收入弹性","options":[],"answer":"商品需求变动对收入变动的反应程度。收入弹性大于1的是奢侈品，0~1之间的是必需品，小于0的是低档商品。","chapter":"名词解释","explanation":"商品需求变动对收入变动的反应程度。收入弹性大于1的是奢侈品，0~1之间的是必需品，小于0的是低档商品。"},{"id":"econ-179","origNo":179,"type":"term","stem":"交叉弹性","options":[],"answer":"是指一种商品需求量变动对另一种商品价格变动的反应程度。交叉弹性小于0时两种商品是互补商品，大于0时两种商品是替代商品，等于0时两种商品不相关。","chapter":"名词解释","explanation":"是指一种商品需求量变动对另一种商品价格变动的反应程度。交叉弹性小于0时两种商品是互补商品，大于0时两种商品是替代商品，等于0时两种商品不相关。"},{"id":"econ-180","origNo":180,"type":"term","stem":"价格弹性（需求价格弹性）","options":[],"answer":"是指商品需求量变动对价格变动的反应程度。","chapter":"名词解释","explanation":"是指商品需求量变动对价格变动的反应程度。"},{"id":"econ-181","origNo":181,"type":"term","stem":"需求弹性","options":[],"answer":"是指相应于影响需求量的某一因素的变动，即需求量变动的反应程度。对应于不同的影响因素，需求弹性可以区分为需求的价格弹性、需求的收入弹性和需求的交叉弹性。需求弹性的大小通常由弹性系数加以表示。","chapter":"名词解释","explanation":"是指相应于影响需求量的某一因素的变动，即需求量变动的反应程度。对应于不同的影响因素，需求弹性可以区分为需求的价格弹性、需求的收入弹性和需求的交叉弹性。需求弹性的大小通常由弹性系数加以表示。"},{"id":"econ-182","origNo":182,"type":"term","stem":"供给弹性","options":[],"answer":"是指相应于影响供给量的某一因素的变动，供给量变动的反应程度。对应于不同的影响因素，供给弹性可以区分为供给的价格弹性、供给的收入弹性和供给的交叉弹性。供给弹性的大小通常由供给弹性系数加以表示。","chapter":"名词解释","explanation":"是指相应于影响供给量的某一因素的变动，供给量变动的反应程度。对应于不同的影响因素，供给弹性可以区分为供给的价格弹性、供给的收入弹性和供给的交叉弹性。供给弹性的大小通常由供给弹性系数加以表示。"},{"id":"econ-183","origNo":183,"type":"term","stem":"效用","options":[],"answer":"效用是指人们消费或拥有一定数量的某种商品时所获得的满足程度。一种商品给消费者所带来的效用不同于该商品的使用价值。效用也是消费者对所消费商品的主观评价，它通常被表示成消费的商品数量的函数。","chapter":"名词解释","explanation":"效用是指人们消费或拥有一定数量的某种商品时所获得的满足程度。一种商品给消费者所带来的效用不同于该商品的使用价值。效用也是消费者对所消费商品的主观评价，它通常被表示成消费的商品数量的函数。"},{"id":"econ-184","origNo":184,"type":"term","stem":"边际效用递减规律","options":[],"answer":"边际效用递减规律是指某消费者在消费某种商品时，随着消费量的增加，新增加的一单位该商品所带给该消费者的效用的增加量，即边际效用将递减。多数商品具有这一规律，但也有例外。边际效用递减规律是基数效用论的一个重要假设。","chapter":"名词解释","explanation":"边际效用递减规律是指某消费者在消费某种商品时，随着消费量的增加，新增加的一单位该商品所带给该消费者的效用的增加量，即边际效用将递减。多数商品具有这一规律，但也有例外。边际效用递减规律是基数效用论的一个重要假设。"},{"id":"econ-185","origNo":185,"type":"term","stem":"边际替代率","options":[],"answer":"边际替代率是无差异曲线的斜率的相反数，他表示某两种商品的替代关系，即一单位商品X可以替代多少单位商品Y，并且保证所获得的效用水平保持不变。MRS一般具有递减趋势（但不排除有例外），表示消费者拥有某种商品越少，就越不愿意用它来换取另外相对富足的商品。","chapter":"名词解释","explanation":"边际替代率是无差异曲线的斜率的相反数，他表示某两种商品的替代关系，即一单位商品X可以替代多少单位商品Y，并且保证所获得的效用水平保持不变。MRS一般具有递减趋势（但不排除有例外），表示消费者拥有某种商品越少，就越不愿意用它来换取另外相对富足的商品。"},{"id":"econ-186","origNo":186,"type":"term","stem":"机会成本","options":[],"answer":"是指生产某种产品耗费的资源所能生产的其他商品的价值。它是对资源配置效率的一种度量。资源配置的效率高，则生产的机会成本低。","chapter":"名词解释","explanation":"是指生产某种产品耗费的资源所能生产的其他商品的价值。它是对资源配置效率的一种度量。资源配置的效率高，则生产的机会成本低。"},{"id":"econ-187","origNo":187,"type":"term","stem":"经济成本","options":[],"answer":"是指按照机会成本计算的成本，包括显性成本（或会计成本）和隐性成本。隐性成本是指会计成本中并不计入，但属于机会成本的那部分成本。","chapter":"名词解释","explanation":"是指按照机会成本计算的成本，包括显性成本（或会计成本）和隐性成本。隐性成本是指会计成本中并不计入，但属于机会成本的那部分成本。"},{"id":"econ-188","origNo":188,"type":"term","stem":"短期成本","options":[],"answer":"是指在生产者来不及调整某些生产要素数量的情况下，生产一定的产出数量所花费的成本。短期成本包括固定成本和可变成本两部分。","chapter":"名词解释","explanation":"是指在生产者来不及调整某些生产要素数量的情况下，生产一定的产出数量所花费的成本。短期成本包括固定成本和可变成本两部分。"},{"id":"econ-189","origNo":189,"type":"term","stem":"长期成本","options":[],"answer":"是指生产者在可以调整所有的生产要素数量的情况下，进行生产所花费的成本。长期成本只包括可变成本。它是短期成本中从长期角度看有最低值的那些成本所组成。","chapter":"名词解释","explanation":"是指生产者在可以调整所有的生产要素数量的情况下，进行生产所花费的成本。长期成本只包括可变成本。它是短期成本中从长期角度看有最低值的那些成本所组成。"},{"id":"econ-190","origNo":190,"type":"term","stem":"生产函数","options":[],"answer":"在特定时间范围内和即定的生产技术水平下，一定的生产要素数量组合与其所能生产的最大产量之间的关系。","chapter":"名词解释","explanation":"在特定时间范围内和即定的生产技术水平下，一定的生产要素数量组合与其所能生产的最大产量之间的关系。"},{"id":"econ-191","origNo":191,"type":"term","stem":"边际收益递减规律","options":[],"answer":"在技术水平不变的条件下，增加一种生产要素的投入，当该生产要素的投入数量增加到一定程度以后，单位生产要素投入增加所带来的产量增加终会出现递减的一条规律。","chapter":"名词解释","explanation":"在技术水平不变的条件下，增加一种生产要素的投入，当该生产要素的投入数量增加到一定程度以后，单位生产要素投入增加所带来的产量增加终会出现递减的一条规律。"},{"id":"econ-192","origNo":192,"type":"term","stem":"内在经济","options":[],"answer":"指一个厂商在生产规模扩大时由自身内部原因所引起的产量增加，其原因主要有：使用先进的机器设备、实现专业化、提高管理效率、综合利用副产品、取得有利的销售条件等。","chapter":"名词解释","explanation":"指一个厂商在生产规模扩大时由自身内部原因所引起的产量增加，其原因主要有：使用先进的机器设备、实现专业化、提高管理效率、综合利用副产品、取得有利的销售条件等。"},{"id":"econ-193","origNo":193,"type":"term","stem":"外在经济","options":[],"answer":"指整个行业生产规模的扩大，给个别厂商所带来的产量和收益的增加。其原因主要有：更方便的交通、更多更灵通的信息、更多更好的人才等。","chapter":"名词解释","explanation":"指整个行业生产规模的扩大，给个别厂商所带来的产量和收益的增加。其原因主要有：更方便的交通、更多更灵通的信息、更多更好的人才等。"},{"id":"econ-194","origNo":194,"type":"term","stem":"技术替代率","options":[],"answer":"等产量线斜率的相反数，它表示两种生产要素之间的技术替代关系，以保持产量不变为前提。技术替代率是递减的，表示在保持产量不变的前提下，某要素投入量越少，越不容易被另外的要素所替代。","chapter":"名词解释","explanation":"等产量线斜率的相反数，它表示两种生产要素之间的技术替代关系，以保持产量不变为前提。技术替代率是递减的，表示在保持产量不变的前提下，某要素投入量越少，越不容易被另外的要素所替代。"},{"id":"econ-195","origNo":195,"type":"essay","stem":"影响商品需求与供给的主要因素分别有哪些？","options":[],"answer":"影响需求的主要因素除了商品本身的价格外，还包括消费者对商品的偏好、消费者的收入水平、替代品和互补品的价格以及消费者对商品价格的未来预期等；而影响供给的主要因素除了商品本身的价格外，还包括厂商的生产技术水平、投入要素价格、其他商品的价格、厂商对价格的未来预期以及市场上厂商数目、税收和补贴等。","chapter":"问答","explanation":"影响需求的主要因素除了商品本身的价格外，还包括消费者对商品的偏好、消费者的收入水平、替代品和互补品的价格以及消费者对商品价格的未来预期等；而影响供给的主要因素除了商品本身的价格外，还包括厂商的生产技术水平、投入要素价格、其他商品的价格、厂商对价格的未来预期以及市场上厂商数目、税收和补贴等。"},{"id":"econ-196","origNo":196,"type":"essay","stem":"运用替代效应和收入效应分析说明，若牛肉价格下降，其需求量必然会增加？","options":[],"answer":"牛肉价格的下降会增加人们对它的需求量，这是替代效应和收入效应共同发生作用的结果。因为当牛肉的价格下降而其他商品（如猪肉）的价格不变时，人们在一定限度内就会少买些猪肉，而把原来用于购买猪肉的钱转而购买牛肉。也就是说，牛肉价格下降会促使人们用牛肉去替代猪肉等其他商品，从而引起对牛肉需求量的增加。这就是价格变化的替代效应。另一方面，由于需求是以人们的购买力为前提的，而人们的购买力主要来自他们的货币收入。其他商品价格不变而牛肉的价格下降，这意味着同样的货币收入在不减少其他商品消费量的情况下，可以购买更多的牛肉。因为牛肉的价格下降实际上表示人们实际收入提高了。这就是收入效应。因此，当作为正常品的牛肉的价格下降时，由于替代效应和收入效应的共同作用，人们对它的需求量会比价格变化前增加。","chapter":"问答","explanation":"牛肉价格的下降会增加人们对它的需求量，这是替代效应和收入效应共同发生作用的结果。因为当牛肉的价格下降而其他商品（如猪肉）的价格不变时，人们在一定限度内就会少买些猪肉，而把原来用于购买猪肉的钱转而购买牛肉。也就是说，牛肉价格下降会促使人们用牛肉去替代猪肉等其他商品，从而引起对牛肉需求量的增加。这就是价格变化的替代效应。另一方面，由于需求是以人们的购买力为前提的，而人们的购买力主要来自他们的货币收入。其他商品价格不变而牛肉的价格下降，这意味着同样的货币收入在不减少其他商品消费量的情况下，可以购买更多的牛肉。因为牛肉的价格下降实际上表示人们实际收入提高了。这就是收入效应。因此，当作为正常品的牛肉的价格下降时，由于替代效应和收入效应的共同作用，人们对它的需求量会比价格变化前增加。"},{"id":"econ-197","origNo":197,"type":"essay","stem":"什么是利润最大化原则","options":[],"answer":"生产理论认为，对一个厂商来说，他的原则就是利润最大化原则。利润最大化的条件就是厂商的边际收益与边际成本相等，即MR=MC。这是因为，如果MR>MC，表明还有潜在利润没有得到，厂商增加生产是有利的。在边际收益即定（至少不增加）的条件下，厂商增加生产的结果是边际成本增加。但是，只要边际收益大于边际成本，厂商就会增加生产，直到两者相等。反之，如果MR<MC，厂商减少生产有利于利润增加。只有在MR=MC时，厂商实现了利润最大化，才会即不增加生产也不减少生产。","chapter":"问答","explanation":"生产理论认为，对一个厂商来说，他的原则就是利润最大化原则。利润最大化的条件就是厂商的边际收益与边际成本相等，即MR=MC。这是因为，如果MR>MC，表明还有潜在利润没有得到，厂商增加生产是有利的。在边际收益即定（至少不增加）的条件下，厂商增加生产的结果是边际成本增加。但是，只要边际收益大于边际成本，厂商就会增加生产，直到两者相等。反之，如果MR<MC，厂商减少生产有利于利润增加。只有在MR=MC时，厂商实现了利润最大化，才会即不增加生产也不减少生产。"},{"id":"econ-198","origNo":198,"type":"essay","stem":"无差异曲线的基本含义","options":[],"answer":"无差异曲线表示消费者对某两种商品的组合的偏好情况，其上任意一点都表示相应的商品组合对该消费者而言具有相同的效用水平，是没有差异的根据偏好的一些假设，可得出无差异曲线具有以下性质：具有负斜率；位置越高的无差异曲线表示的效用水平越高；任意两条无差异曲线都不相交；无差异曲线族具有密集性；无差异曲线斜率的相反数即边际替代率MRS是递减的。无差异曲线作为消费者偏好的体现，在消费者行为分析中起着重要的作用。","chapter":"问答","explanation":"无差异曲线表示消费者对某两种商品的组合的偏好情况，其上任意一点都表示相应的商品组合对该消费者而言具有相同的效用水平，是没有差异的根据偏好的一些假设，可得出无差异曲线具有以下性质：具有负斜率；位置越高的无差异曲线表示的效用水平越高；任意两条无差异曲线都不相交；无差异曲线族具有密集性；无差异曲线斜率的相反数即边际替代率MRS是递减的。无差异曲线作为消费者偏好的体现，在消费者行为分析中起着重要的作用。"},{"id":"econ-199","origNo":199,"type":"essay","stem":"粮食价格提高对猪肉的供给曲线有何影响？猪肉价格提高对猪肉销售量和猪肉供给曲线是否会发生影响？","options":[],"answer":"粮食价格的提高将使猪肉的供给曲线向左上方移动。因为粮价提高将使猪的饲养成本上升，进而在任一价格水平下生产者愿意并且能够提供的猪肉量随之减少。猪肉价格提高将增加猪肉的销售量。因为在其他因素不变的情况下，猪肉价格提高意味着增加猪肉这种商品的供应量将变得更加有利可图，因此生产和销售者提供更多的猪肉上市，这表现为猪肉供给曲线上点的位置的移动。但猪肉价格提高本身并不会对供给曲线的变动产生影响。","chapter":"问答","explanation":"粮食价格的提高将使猪肉的供给曲线向左上方移动。因为粮价提高将使猪的饲养成本上升，进而在任一价格水平下生产者愿意并且能够提供的猪肉量随之减少。猪肉价格提高将增加猪肉的销售量。因为在其他因素不变的情况下，猪肉价格提高意味着增加猪肉这种商品的供应量将变得更加有利可图，因此生产和销售者提供更多的猪肉上市，这表现为猪肉供给曲线上点的位置的移动。但猪肉价格提高本身并不会对供给曲线的变动产生影响。"},{"id":"econ-200","origNo":200,"type":"essay","stem":"需求的价格弹性的高低对生产者的总收益有什么影响？","options":[],"answer":"当价格下降时，如果需求的价格弹性大于1，需求量增加幅度较大，厂商的总收益增加；如果需求的价格弹性小于1，需求量没什么变化，厂商的总收益减少。当价格上升时，如果需求的价格弹性大于1，需求量减少幅度较大，厂商的总收益减少；如果需求的价格弹性小于1，需求量没什么变化，厂商的总收益增加。","chapter":"问答","explanation":"当价格下降时，如果需求的价格弹性大于1，需求量增加幅度较大，厂商的总收益增加；如果需求的价格弹性小于1，需求量没什么变化，厂商的总收益减少。当价格上升时，如果需求的价格弹性大于1，需求量减少幅度较大，厂商的总收益减少；如果需求的价格弹性小于1，需求量没什么变化，厂商的总收益增加。"},{"id":"econ-201","origNo":201,"type":"essay","stem":"什么是完全竞争市场？","options":[],"answer":"微观经济学对完全竞争市场作了如下明确的定义，符合以下四个条件的市场就是完全竞争市场：①市场上有无数的买者和卖者，每个消费者和生产者都是市场价格的被动接收者，对市场价格没有任何控制力量；②同一行业中的每一个厂商生产的产品是同质的；③厂商进入或退出一个行业是完全自由的；④市场中的每一个买者和卖者都是完全信息的，即掌握与自己的经济决策相关的商品和市场的全部信息。","chapter":"问答","explanation":"微观经济学对完全竞争市场作了如下明确的定义，符合以下四个条件的市场就是完全竞争市场：①市场上有无数的买者和卖者，每个消费者和生产者都是市场价格的被动接收者，对市场价格没有任何控制力量；②同一行业中的每一个厂商生产的产品是同质的；③厂商进入或退出一个行业是完全自由的；④市场中的每一个买者和卖者都是完全信息的，即掌握与自己的经济决策相关的商品和市场的全部信息。"},{"id":"econ-202","origNo":202,"type":"essay","stem":"试述垄断竞争市场的基本含义及其特征","options":[],"answer":"垄断竞争市场是指竞争程度介于完全竞争市场和寡头市场之间的一种市场结构。在该市场上，大量的企业生产有差别的同种产品，这些产品在质量、构造、外观、商标以及销售服务条件等方面存在差异，有时这种差别来自于消费者的心理，但这些产品彼此之间又都是非常接近的替代品。另外，市场上企业的规模较小，数量众多，以致于每个厂商在作出行为时都不考虑竞争对手的反应。由于厂商生产规模较小，因而，进入和退出市场比较容易。垄断竞争市场是现实生活中比较普遍的一种市场结构。","chapter":"问答","explanation":"垄断竞争市场是指竞争程度介于完全竞争市场和寡头市场之间的一种市场结构。在该市场上，大量的企业生产有差别的同种产品，这些产品在质量、构造、外观、商标以及销售服务条件等方面存在差异，有时这种差别来自于消费者的心理，但这些产品彼此之间又都是非常接近的替代品。另外，市场上企业的规模较小，数量众多，以致于每个厂商在作出行为时都不考虑竞争对手的反应。由于厂商生产规模较小，因而，进入和退出市场比较容易。垄断竞争市场是现实生活中比较普遍的一种市场结构。"},{"id":"econ-203","origNo":203,"type":"essay","stem":"什么是超额利润？它主要有哪些来源","options":[],"answer":"超额利润是指超过正常利润的那一部分利润，又称为净利润、纯粹利润或经济利润。超额利润又别于正常利润。正常利润是企业家才能的价格，也是企业家才能这一生产要素的收入，它由该要素的供给和需求的均衡所决定。而超额利润是企业收益减去包括正常利润在内的成本之后的余额。  超额利润有几种来源。第一种来源是，超额利润是创新的报酬。创新给企业带来利润，促进社会进步。第二种来源是，超额利润是承担风险的报酬。在经济社会中，风险是普遍存在的。一项决策可能带来超额利润，也可能出现亏损，承担风险就需要获得报酬。第三种来源是，超额利润是垄断收益。无论是卖方垄断还是买方垄断，厂商都可以通过市场支配力来影响产品或生产要素价格，从而获得超额利润。","chapter":"问答","explanation":"超额利润是指超过正常利润的那一部分利润，又称为净利润、纯粹利润或经济利润。超额利润又别于正常利润。正常利润是企业家才能的价格，也是企业家才能这一生产要素的收入，它由该要素的供给和需求的均衡所决定。而超额利润是企业收益减去包括正常利润在内的成本之后的余额。  超额利润有几种来源。第一种来源是，超额利润是创新的报酬。创新给企业带来利润，促进社会进步。第二种来源是，超额利润是承担风险的报酬。在经济社会中，风险是普遍存在的。一项决策可能带来超额利润，也可能出现亏损，承担风险就需要获得报酬。第三种来源是，超额利润是垄断收益。无论是卖方垄断还是买方垄断，厂商都可以通过市场支配力来影响产品或生产要素价格，从而获得超额利润。"},{"id":"econ-204","origNo":204,"type":"essay","stem":"试比较消费者行为理论与生产者行为理论。","options":[],"answer":"⑴消费者行为理论和生产者行为理论都假设行为人是理性的，即消费者是追求效用最大化，生产者是追求利润最大化的；⑵消费者行为理论的目的是解释消费者行为，并把分析结果总结在需求曲线中，为供求论的使用奠定基础。而生产者行为理论的目的则是解释生产者行为，并把分析结果总结在供给曲线中，也作为供求论研究价格决定的基础；⑶消费者行为理论中序数效用论使用的分析工具为无差异曲线和预算约束线，二者的切点即为消费者均衡点。生产者行为理论使用的分析工具有些也类似，如等产量线和等成本线，二者的切点即为生产者均衡点；⑷二者都是供求论的基石。","chapter":"问答","explanation":"⑴消费者行为理论和生产者行为理论都假设行为人是理性的，即消费者是追求效用最大化，生产者是追求利润最大化的；⑵消费者行为理论的目的是解释消费者行为，并把分析结果总结在需求曲线中，为供求论的使用奠定基础。而生产者行为理论的目的则是解释生产者行为，并把分析结果总结在供给曲线中，也作为供求论研究价格决定的基础；⑶消费者行为理论中序数效用论使用的分析工具为无差异曲线和预算约束线，二者的切点即为消费者均衡点。生产者行为理论使用的分析工具有些也类似，如等产量线和等成本线，二者的切点即为生产者均衡点；⑷二者都是供求论的基石。"},{"id":"econ-205","origNo":205,"type":"essay","stem":"简述寡头垄断市场的特征。","options":[],"answer":"寡头市场是指少数几家厂商控制整个行业产品的生产和销售的一种市场结构。在寡头市场上，每个厂商的产量都在全行业的总产量中占有较大的分额，从而每个厂商的产量和价格的变动都会都其他竞争对手产生影响。因此，寡头垄断市场呈现出不同于其他市场的特征，这主要表现在：寡头厂商之间存在着彼此认识到的相互依存性；寡头垄断市场的价格具有相对稳定性（主要依靠广告竞争和产品质量竞争）；寡头市场厂商行为结果的不确定性。","chapter":"问答","explanation":"寡头市场是指少数几家厂商控制整个行业产品的生产和销售的一种市场结构。在寡头市场上，每个厂商的产量都在全行业的总产量中占有较大的分额，从而每个厂商的产量和价格的变动都会都其他竞争对手产生影响。因此，寡头垄断市场呈现出不同于其他市场的特征，这主要表现在：寡头厂商之间存在着彼此认识到的相互依存性；寡头垄断市场的价格具有相对稳定性（主要依靠广告竞争和产品质量竞争）；寡头市场厂商行为结果的不确定性。"},{"id":"econ-206","origNo":206,"type":"essay","stem":"简述完全竞争条件下，某生产要素的市场需求曲线与一般厂商需求曲线的差异","options":[],"answer":"生产要素市场需求曲线是指整个行业对某种生产工具要素的总需求曲线。这条总需求曲线是和产品的市场需求曲线不一样，不能直接将行业中所有个别厂商对该要素的需求曲线简单加总。其原因是生产要素的需求是一种派生需求，如果生产要素的价格下降，会导致所有厂商对该要素需求的增加以扩大正常规模。但是，当生产要素规模扩大后，产品的总供给会相应增加，如果市场需求不变，产品的价格就会下跌。而产品价格的下跌则又会导致对要素需求的减少。这时，个别厂商对生产要素的需求曲线将会向左移动。因此，在新的价格下，整个市场对该生产工具要素的总需求要比单个厂商对该要素需求的简单加总要小，是个别厂商要素需求曲线左移动的总和。经济学上把这种由于产品价格下降所造成的对个别厂商要素需求的影响称为“外部效应”。","chapter":"问答","explanation":"生产要素市场需求曲线是指整个行业对某种生产工具要素的总需求曲线。这条总需求曲线是和产品的市场需求曲线不一样，不能直接将行业中所有个别厂商对该要素的需求曲线简单加总。其原因是生产要素的需求是一种派生需求，如果生产要素的价格下降，会导致所有厂商对该要素需求的增加以扩大正常规模。但是，当生产要素规模扩大后，产品的总供给会相应增加，如果市场需求不变，产品的价格就会下跌。而产品价格的下跌则又会导致对要素需求的减少。这时，个别厂商对生产要素的需求曲线将会向左移动。因此，在新的价格下，整个市场对该生产工具要素的总需求要比单个厂商对该要素需求的简单加总要小，是个别厂商要素需求曲线左移动的总和。经济学上把这种由于产品价格下降所造成的对个别厂商要素需求的影响称为“外部效应”。"}]};
